/**
 * NE:       Uygulama çökme koruması (React Error Boundary) — sakin, dürüst geri dönüş ekranı.
 * NEDEN:    "Kusursuz çalışma" (Mehmet abi) + yol haritası: bir render hatası TÜM uygulamayı beyaz/boş
 *           ekrana düşürmemeli. Kullanıcı finansal karar aracında panik/boşluk görmemeli; sakin bir
 *           "yeniden dene" ile devam edebilmeli. Karar verisi cihazda kalır; çökme kullanıcı verisini kaybetmez.
 * NASIL:    Sınıf bileşeni; getDerivedStateFromError ile hata yakalanır, sakin premium fallback gösterilir.
 *           "Yeniden dene" durumu sıfırlar. Üretimde componentDidCatch bir çökme günlükleyicisine (Sentry)
 *           bağlanacak yer — şimdilik konsola yazar (PII yok).
 * YAN ETKİ: Yalnız yerel state; ağ/veri yok. Hata yoksa tamamen şeffaftır (children'ı aynen basar).
 */
import { Component, type ReactNode } from "react";
import { StyleSheet, Text, View } from "react-native";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";

interface Props {
  children: ReactNode;
}
interface State {
  hata: boolean;
}

export class HataSiniri extends Component<Props, State> {
  state: State = { hata: false };

  static getDerivedStateFromError(): State {
    return { hata: true };
  }

  componentDidCatch(hata: unknown): void {
    // Üretimde: çökme günlükleyicisi (Sentry) — PII maskeli. Şimdilik geliştirici konsolu.
    console.error("KartAkıl render hatası yakalandı:", hata);
  }

  yenidenDene = (): void => {
    this.setState({ hata: false });
  };

  render(): ReactNode {
    if (!this.state.hata) return this.props.children;
    return (
      <View style={s.kap} accessibilityLabel="Bir şeyler ters gitti">
        <View style={s.amblem}>
          <View style={s.kart} />
          <View style={s.yildiz} />
        </View>
        <Text style={s.baslik} accessibilityRole="header">
          Bir şeyler ters gitti
        </Text>
        <Text style={s.yazi}>
          Beklenmedik bir durum oldu. Kartların ve karnen telefonunda güvende — hiçbir şey kaybolmadı.
          Yeniden deneyebilirsin.
        </Text>
        <Basilabilir
          onPress={this.yenidenDene}
          stil={s.buton}
          accessibilityRole="button"
          accessibilityLabel="Yeniden dene"
          teknolojiRenk={TEMA.renk.altinAcik}
        >
          <Text style={s.butonYazi}>Yeniden dene</Text>
        </Basilabilir>
      </View>
    );
  }
}

const s = StyleSheet.create({
  kap: {
    flex: 1,
    backgroundColor: TEMA.renk.zemin,
    alignItems: "center",
    justifyContent: "center",
    padding: TEMA.bosluk.xl,
    gap: TEMA.bosluk.m,
  },
  amblem: {
    width: 64,
    height: 64,
    borderRadius: 18,
    backgroundColor: TEMA.yuzey.kat2.zemin,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    alignItems: "center",
    justifyContent: "center",
    marginBottom: TEMA.bosluk.s,
  },
  kart: { width: 30, height: 20, borderRadius: 4, borderWidth: 2.5, borderColor: TEMA.renk.altin },
  yildiz: {
    position: "absolute",
    top: 12,
    right: 12,
    width: 10,
    height: 10,
    borderRadius: 5,
    backgroundColor: TEMA.renk.altinAcik,
  },
  baslik: { color: TEMA.renk.yazi, fontSize: 18, fontWeight: "800", textAlign: "center" },
  yazi: { color: TEMA.renk.yaziSoluk, fontSize: 13, lineHeight: 19, textAlign: "center", maxWidth: 320 },
  buton: {
    minHeight: 48,
    borderRadius: TEMA.yaricap.hap,
    backgroundColor: TEMA.renk.altin,
    paddingHorizontal: TEMA.bosluk.xxl,
    paddingVertical: TEMA.bosluk.m,
    justifyContent: "center",
    marginTop: TEMA.bosluk.s,
  },
  butonYazi: { color: TEMA.renk.zeminKoyu, fontWeight: "800", fontSize: 14 },
});
