/**
 * NE:       Dokunsal (haptik) geri bildirim sarmalayıcısı — premium his, özellikle iPhone.
 * NEDEN:    Sekme değişince / kart çevirince hafif titreşim = "yaşayan", premium arayüz.
 *           Mehmet abi iPhone kullanıyor; standart iOS deseni (seçim/hafif dokunuş).
 * NASIL:    expo-haptics'i güvenli çağırır; web'de ve desteklemeyen platformda sessizce no-op
 *           (Promise reddi yutulur). Yalnız ayrık kullanıcı eylemine bağlanır — sürekli/typing anına DEĞİL.
 * YAN ETKİ: Yalnız cihaz titreşimi; ağ/veri yok. Web export'ta hiçbir etki yok.
 */
import { Platform } from "react-native";
import * as Haptics from "expo-haptics";

/** Kart çevirme, buton basımı gibi ayrık dokunuş — hafif darbe. */
export function dokunsalHafif(): void {
  if (Platform.OS === "web") return;
  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
}

/** Sekme/seçim değişimi — iOS seçim haptiği. */
export function dokunsalSecim(): void {
  if (Platform.OS === "web") return;
  Haptics.selectionAsync().catch(() => {});
}

/** Kilometre taşı / kişisel rekor kutlaması — güçlü başarı bildirimi (tören anı). */
export function dokunsalBasari(): void {
  if (Platform.OS === "web") return;
  Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
}
