/**
 * NE: Native OTA güncellemesinin kullanıcıya duyurulup duyurulmayacağını saf biçimde kararlaştırır.
 * NEDEN: İlk gömülü paket, web ve daha önce onaylanan updateId yanlışlıkla tekrar güncelleme kutusu açmamalıdır.
 * NASIL: Platform, embedded durumu, güncel updateId ve cihazda görülen son kimliği fail-closed karşılaştırır.
 * YAN ETKİ: Yoktur; depolama, ağ veya UI çağrısı yapmaz.
 */
export function duyurulacakNativeGuncellemeKimligi(
  platform: string,
  embedded: boolean,
  updateId: string | null,
  sonGorulenUpdateId: string | null,
): string | null {
  if (platform === "web" || embedded || !updateId || updateId === sonGorulenUpdateId) return null;
  return updateId;
}
