/**
 * NE:       Cihaz konumuyla Google Places'ten (New) çevredeki BİLİNEN markaları çeker → YakinMagaza[].
 * NEDEN:    Kendi şube listesini elle derlemek ölçeklenmiyordu (her marka ayrı kaynak, hep eksik,
 *           yalnız Kayseri). Places tüm Türkiye + tüm markaları güncel verir. Sadece kampanyası olan
 *           (bilinen) markalar tutulur; alakasız işletme elenir.
 * NASIL:    Konum → places:searchNearby (kategori tipleri + yarıçap). Dönen ad markaTani ile bilinen
 *           markaya eşlenir, marka başına en yakın şube seçilir. Konum YALNIZ Google'a gider (bizim
 *           sunucuya DEĞİL, saklanmaz) — cihazdan doğrudan çağrı. Anahtar yoksa null → çağıran yerel
 *           Kayseri listesine düşer (mevcut davranış bozulmaz).
 * YAN ETKİ: Tek dış HTTP çağrısı (Google). Kalıcı kayıt/izleme yok.
 */
import { markaTani } from "../motor/markaTani";
import { mesafeM, koordinatGecerliMi, type YakinMagaza } from "../motor/konumHesap";

const ANAHTAR = process.env.EXPO_PUBLIC_GOOGLE_PLACES_KEY ?? "";
const UCPOINT = "https://places.googleapis.com/v1/places:searchNearby";

// Kategori GRUPLARI — her grup ayrı çağrı (DISTANCE). Tek karışık çağrıda yoğun bölgede bizim markalar
// azınlıkta kalıyordu; grup başına en yakın 20 → her kategoriden yakın markalar (akaryakıtta Shell/Opet/BP,
// markette Migros/A101/BİM hepsi çıkar).
const GRUPLAR: string[][] = [
  ["supermarket", "grocery_store", "convenience_store", "department_store"],
  ["gas_station"],
  ["electronics_store", "clothing_store", "shoe_store", "home_goods_store", "furniture_store", "hardware_store", "pharmacy", "drugstore", "book_store"],
];

export function placesEtkinMi(): boolean {
  return ANAHTAR.length > 0;
}

/**
 * Konum çevresindeki bilinen markaları döndürür. Anahtar yok / hata / boş → null (çağıran fallback yapar).
 * `markalar` = MARKA_KATEGORI anahtarları (App geçirir; kod marka adı hardcode etmez).
 */
export async function yakinPlacesAra(
  lat: number,
  lon: number,
  markalar: readonly string[],
  adet = 40,
  yaricapM = 8000,
  markaBasinaAzami = 3
): Promise<YakinMagaza[] | null> {
  if (!ANAHTAR || !koordinatGecerliMi(lat, lon)) return null;

  async function grubuAra(tipler: string[]): Promise<unknown[]> {
    try {
      const yanit = await fetch(UCPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Goog-Api-Key": ANAHTAR,
          "X-Goog-FieldMask": "places.displayName,places.location,places.primaryType",
        },
        body: JSON.stringify({
          includedTypes: tipler,
          maxResultCount: 20,
          // EN YAKIN öncelikli (varsayılan POPULARITY yanı başındaki Shell'i atlıyordu → DISTANCE).
          rankPreference: "DISTANCE",
          languageCode: "tr",
          locationRestriction: { circle: { center: { latitude: lat, longitude: lon }, radius: yaricapM } },
        }),
      });
      if (!yanit.ok) return [];
      const veri: unknown = await yanit.json();
      const yerler = (veri as { places?: unknown[] }).places;
      return Array.isArray(yerler) ? yerler : [];
    } catch {
      return [];
    }
  }

  try {
    const gruplar = await Promise.all(GRUPLAR.map((g) => grubuAra(g)));
    const tumYerler = gruplar.flat();
    if (tumYerler.length === 0) return null;

    // Tüm geçerli adayları topla (marka tanınan + koordinatı geçerli).
    const adaylar: YakinMagaza[] = [];
    for (const y of tumYerler) {
      const yer = y as { displayName?: { text?: string }; location?: { latitude?: number; longitude?: number } };
      const ham = yer.displayName?.text ?? "";
      const marka = markaTani(ham, markalar);
      if (!marka) continue;
      const plat = yer.location?.latitude;
      const plon = yer.location?.longitude;
      if (typeof plat !== "number" || typeof plon !== "number" || !koordinatGecerliMi(plat, plon)) continue;
      adaylar.push({
        marka,
        subeAd: ham.slice(0, 60) || marka,
        mesafeM: mesafeM(lat, lon, plat, plon),
        lat: plat,
        lon: plon,
      });
    }

    // En yakından uzağa sırala; marka başına EN FAZLA `markaBasinaAzami` şube (tek marka listeyi
    // boğmasın ama "yanımda 2-3 Migros" da görünüp yol tarifi için seçilebilsin); aynı şube
    // (marka + ad + ~konum) tekrarını ele. Böylece liste uzar ama anlamlı kalır.
    adaylar.sort((a, b) => a.mesafeM - b.mesafeM);
    const markaSayac = new Map<string, number>();
    const gorulen = new Set<string>();
    const sonuc: YakinMagaza[] = [];
    for (const a of adaylar) {
      const kimlik = `${a.marka}|${a.subeAd}|${a.lat.toFixed(4)},${a.lon.toFixed(4)}`;
      if (gorulen.has(kimlik)) continue;
      const say = markaSayac.get(a.marka) ?? 0;
      if (say >= markaBasinaAzami) continue;
      gorulen.add(kimlik);
      markaSayac.set(a.marka, say + 1);
      sonuc.push(a);
      if (sonuc.length >= adet) break;
    }
    return sonuc.length > 0 ? sonuc : null;
  } catch {
    return null;
  }
}
