/**
 * NE:       Karar ekranındaki konumdan bul veya elle mağaza seç akışı.
 * NEDEN:    Konum izni reddedildiğinde kategori seçmek gerçek mağaza teyidi değildir;
 *           kullanıcı ana işi izin vermeden de tamamlayabilmeli, açık seçim alanını web ekran
 *           okuyucusu da durumuyla birlikte anlayabilmelidir.
 * NASIL:    Yakındaki en güçlü adayları ve cihazdaki pilot mağaza listesini tek, erişilebilir
 *           yüzeyde sunar; normal akışta dinamik aç/kapat etiketiyle native accessibilityState ve
 *           web aria-expanded'ı eşler, zorunlu fallback açıkken işlevsiz toggle'ı gizler.
 * YAN ETKİ: Yerel arama metni bileşen içinde tutulur; fallback açıkken konum eylemi satırı doldurur;
 *           ağ çağrısı ve kalıcı veri yazımı yoktur.
 */
import { useEffect, useMemo, useState, type ReactNode } from "react";
import {
  Animated,
  ImageBackground,
  StyleSheet,
  Text,
  TextInput,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { magazaRenk } from "../marka/magazaLogolari";
import type { KullaniciKonumu } from "../motor/gercekHarita";
import { mesafeYaz, type YakinMagaza } from "../motor/konum";
import { yolTarifiAc } from "../veri/haritaKopru";
import { TEMA } from "../tema";
import { useGiris } from "../hareket";
import { MagazaRozeti } from "./MagazaRozeti";
import { MagazaHero } from "./MagazaHero";
import { Iskelet } from "./Iskelet";
import { Basilabilir } from "./Basilabilir";
import { YakinCevreHaritasi } from "./YakinCevreHaritasi";

/**
 * NE:       Bir liste öğesini yay-fizikli sıralı belirişle (useGiris) saran küçük sunum sarmalı.
 * NEDEN:    useGiris bir kancadır; doğrudan .map() içinde çağrılamaz (Hook kuralı). Her map öğesi
 *           kendi bileşen örneği olan bu sarmalı render edince, useGiris öğe başına tek ve üst
 *           seviyede çağrılır — Karar sekmesindeki SonucSatiri ile aynı sinematik giriş dili
 *           mağaza listelerine de yayılır (kimlik sapmadan).
 * NASIL:    useGiris(sira, hareketAzalt) → opacity + translateY(14→0) yay fizikli beliriş; dış stil
 *           ile birleşip Animated.View'e verilir. Stagger yalnız ilk 8 öğeye (useGiris içinde),
 *           delay tek-atış — LOOP YOK, idle animasyon yok.
 * YAN ETKİ: Yok — saf sunum sarmalı; hareketAzalt=true'da animasyon hiç başlamaz (öğe anında yerinde),
 *           veri/karar mantığına dokunmaz.
 */
function GirisSatir({
  sira,
  hareketAzalt,
  stil,
  children,
}: {
  sira: number;
  hareketAzalt: boolean;
  stil?: StyleProp<ViewStyle>;
  children: ReactNode;
}) {
  const giris = useGiris(sira, hareketAzalt);
  return <Animated.View style={[stil, giris]}>{children}</Animated.View>;
}

export type MagazaSecimKaynak = "location" | "manual";

export type SeciliMagaza = {
  marka: string;
  subeAd: string | null;
  kaynak: MagazaSecimKaynak;
};

type YakinDurum = "kapali" | "araniyor" | "hazir" | "izinsiz";

type MagazaSeciciProps = {
  secili: SeciliMagaza | null;
  yakinDurum: YakinDurum;
  yakinlar: YakinMagaza[];
  kullaniciKonumu: KullaniciKonumu | null;
  tumMagazalar: string[];
  hareketAzalt?: boolean;
  onKonumlaAra: () => void;
  onSec: (secim: SeciliMagaza) => void;
  onTemizle: () => void;
};

function aramaKimligi(deger: string): string {
  return deger
    .toLocaleLowerCase("tr-TR")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ı/g, "i")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

export function MagazaSecici({
  secili,
  yakinDurum,
  yakinlar,
  kullaniciKonumu,
  tumMagazalar,
  hareketAzalt = false,
  onKonumlaAra,
  onSec,
  onTemizle,
}: MagazaSeciciProps) {
  /*
   * NE: Mağaza seçiciden artık kullanılmayan kategori aktarımını kaldırır.
   * NEDEN: Seçili mağaza hero'su marka kimliğine geçti; kategori prop zinciri ölü kaldı.
   * NASIL: MagazaSecici ve MagazaHero sözleşmelerini aynı dar yüzeye getirir.
   * YAN ETKİ: Konum, arama ve mağaza seçimi değişmez.
   */
  const [manuelAcik, setManuelAcik] = useState(false);
  const [arama, setArama] = useState("");
  const [tumYakinlariGoster, setTumYakinlariGoster] = useState(false);
  useEffect(() => {
    setTumYakinlariGoster(false);
  }, [yakinlar]);
  const manuelZorunlu =
    yakinDurum === "izinsiz" || (yakinDurum === "hazir" && yakinlar.length === 0);
  const manuelGoster = manuelAcik || manuelZorunlu;
  const aramaId = aramaKimligi(arama);
  const sonuclar = useMemo(
    () =>
      tumMagazalar
        .filter((marka) => aramaId.length === 0 || aramaKimligi(marka).includes(aramaId))
        .slice(0, aramaId.length === 0 ? 8 : 12),
    [aramaId, tumMagazalar]
  );
  const gorunenYakinlar = tumYakinlariGoster ? yakinlar : yakinlar.slice(0, 6);

  if (secili) {
    // Seçili mağaza kartı = zengin sahne (kategori görseli + logo) + Değiştir. Tek yüzey — çift teyit yok.
    return (
      <MagazaHero
        marka={secili.marka}
        subeAd={secili.subeAd}
        kaynak={secili.kaynak}
        onDegistir={() => {
          onTemizle();
          setManuelAcik(true);
        }}
      />
    );
  }

  return (
    <View style={s.kap}>
      {yakinDurum === "kapali" ? (
        /*
         * NE: Ana menünün ilk yüzünü gerçek bir market kasası ve doğru karta uzanan el sahnesiyle kurar.
         * NEDEN: Eski soyut lokasyon görseli ürünün “kasada hangi kart?” değerini hissettirmiyor; ayrı App
         *       hero'suyla birleşince iki afiş art arda geliyordu.
         * NASIL: Metinsiz, marka/logosuz üretilen crop-safe görsele kontrollü koyu katman ve üç satırlı
         *       değer hiyerarşisi bindirir; eylemler hemen altındaki erişilebilir düğmeler olarak kalır.
         * YAN ETKİ: Konum izni kendiliğinden istenmez; ağ, seçim ve karar davranışı değişmez. Yeni WebP 55 KB'dir.
         */
        <ImageBackground
          source={require("../../assets/sahneler/karar-ani-v3.webp")}
          style={s.konumHero}
          imageStyle={s.konumHeroGorsel}
          resizeMode="cover"
          accessibilityRole="image"
          accessibilityLabel="Market kasasında üç kart arasından doğru kartın altın ışıkla öne çıktığı karar anı"
        >
          <View style={s.konumHeroKarartma} />
          <View style={s.konumHeroIcerik}>
            <Text style={s.konumHeroEtiket}>KASADA TEK SORU</Text>
            <Text style={s.konumHeroBaslik}>Hangi kart?</Text>
            <Text style={s.konumHeroAlt}>Mağazanı seç; en kazançlı kartını ben hesaplayayım.</Text>
          </View>
        </ImageBackground>
      ) : null}
      <View style={s.eylemSatir}>
        <Basilabilir
          onPress={onKonumlaAra}
          disabled={yakinDurum === "araniyor"}
          stil={[s.anaEylem, yakinDurum === "araniyor" && s.pasif]}
          hareketAzalt={hareketAzalt}
          accessibilityRole="button"
          accessibilityState={{ busy: yakinDurum === "araniyor", disabled: yakinDurum === "araniyor" }}
          accessibilityLabel="Konumumla yakındaki mağazaları bul"
        >
          <Text style={s.anaEylemYazi}>
            {yakinDurum === "araniyor" ? "◌ Yakınlara bakılıyor" : "⌖ Yakınımda bul"}
          </Text>
        </Basilabilir>
        {!manuelZorunlu ? (
          <Basilabilir
            onPress={() => setManuelAcik((acik) => !acik)}
            stil={s.ikincilEylem}
            hareketAzalt={hareketAzalt}
            accessibilityRole="button"
            accessibilityState={{ expanded: manuelGoster }}
            aria-expanded={manuelGoster}
            accessibilityLabel={manuelGoster ? "Elle mağaza seçimini kapat" : "Mağazayı kendim seç"}
          >
            <Text style={s.ikincilEylemYazi}>
              {manuelGoster ? "Kapat" : "Kendim seç"}
            </Text>
          </Basilabilir>
        ) : null}
      </View>

      {yakinDurum === "araniyor" ? (
        <View style={s.adayAlan} accessibilityLabel="Yakınındaki mağazalar aranıyor">
          <Text style={s.altBaslik}>Yakınındakiler bulunuyor…</Text>
          <Iskelet boy={52} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} />
          <Iskelet boy={52} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} />
          <Iskelet boy={52} yaricap={TEMA.yaricap.orta} hareketAzalt={hareketAzalt} />
        </View>
      ) : null}

      {yakinDurum === "izinsiz" ? (
        <View style={s.bilgi} accessibilityRole="alert">
          <Text style={s.bilgiBaslik}>Konum olmadan da devam edebilirsin</Text>
          <Text style={s.bilgiYazi}>
            Aşağıdan mağazayı seç. Konum izni verirsen, yakınını bulmak için yalnız harita
            servisine (Google) sorulur — KartAkıl'ın sunucusuna gitmez, saklanmaz.
          </Text>
        </View>
      ) : null}

      {yakinDurum === "hazir" && yakinlar.length > 0 ? (
        <View style={s.adayAlan}>
          {kullaniciKonumu ? (
            <YakinCevreHaritasi konum={kullaniciKonumu} yakinlar={yakinlar} />
          ) : null}
          {/*
           * NE: Yakın mağazaları gerçek mevki haritasının altında, marka kimlikli seçim kartlarına dönüştürür.
           * NEDEN: Eski logo satırı + ayrı yol düğmesi monoton, parçalı ve uzun listede taranması zordu.
           * NASIL: İlk altı yer yakınlık sırasını korur; kart marka rengi, mesafe, en yakın rozeti,
           *       tekincil yol tarifi ve belirgin “Burayı seç” eylemini aynı yüzeyde toplar.
           * YAN ETKİ: İlk görünüm altı kartla sakin kalır; diğer sonuçlar açık kullanıcı eylemiyle gösterilir.
           */}
          <View style={s.listeBaslikSatir}>
            <View>
              <Text style={s.listeBaslik}>Sana en yakın yerler</Text>
              <Text style={s.listeAlt}>{yakinlar.length} uygun yer bulundu · en yakından uzağa</Text>
            </View>
            <View style={s.canliRozet}>
              <Text style={s.canliRozetYazi}>● CANLI KONUM</Text>
            </View>
          </View>
          {gorunenYakinlar.map((magaza, i) => (
            <GirisSatir
              key={`${magaza.marka}-${magaza.subeAd}`}
              sira={i}
              hareketAzalt={hareketAzalt}
              stil={s.yakinKartDis}
            >
              <View style={[s.yakinKart, { borderColor: `${magazaRenk(magaza.marka)}66` }]}>
                <View style={s.yakinUst}>
                  <View style={[s.siraRozeti, { backgroundColor: magazaRenk(magaza.marka) }]}>
                    <Text style={s.siraRozetiYazi}>{i + 1}</Text>
                  </View>
                  <View style={s.yakinKimlik}>
                    <MagazaRozeti
                      marka={magaza.marka}
                      altYazi={`${magaza.subeAd} · ${mesafeYaz(magaza.mesafeM)}`}
                    />
                  </View>
                  {i === 0 ? (
                    <View style={s.enYakinRozet}>
                      <Text style={s.enYakinYazi}>EN YAKIN</Text>
                    </View>
                  ) : null}
                </View>
                <View style={s.yakinEylemler}>
                  <Basilabilir
                    onPress={() =>
                      onSec({ marka: magaza.marka, subeAd: magaza.subeAd, kaynak: "location" })
                    }
                    stil={s.secBtn}
                    hareketAzalt={hareketAzalt}
                    accessibilityRole="button"
                    accessibilityLabel={`${magaza.marka}, ${magaza.subeAd}, ${mesafeYaz(magaza.mesafeM)}, mağazayı seç`}
                  >
                    <Text style={s.secBtnYazi}>Burayı seç</Text>
                  </Basilabilir>
                  <Basilabilir
                    onPress={() => yolTarifiAc(magaza.lat, magaza.lon, magaza.marka)}
                    stil={s.yolBtn}
                    hareketAzalt={hareketAzalt}
                    accessibilityRole="button"
                    accessibilityLabel={`${magaza.marka} ${magaza.subeAd} için yol tarifi aç`}
                    accessibilityHint="Harita uygulamasında navigasyon açılır"
                  >
                    <Text style={s.yolYazi}>Yol tarifi ↗</Text>
                  </Basilabilir>
                </View>
              </View>
            </GirisSatir>
          ))}
          {yakinlar.length > 6 ? (
            <Basilabilir
              onPress={() => setTumYakinlariGoster((goster) => !goster)}
              stil={s.tumunuGoster}
              hareketAzalt={hareketAzalt}
              accessibilityRole="button"
              accessibilityState={{ expanded: tumYakinlariGoster }}
              accessibilityLabel={
                tumYakinlariGoster
                  ? "Yakın yer listesini ilk altı mağazaya daralt"
                  : `${yakinlar.length - 6} yakın yeri daha göster`
              }
            >
              <Text style={s.tumunuGosterYazi}>
                {tumYakinlariGoster ? "İlk 6 yeri göster ↑" : `+${yakinlar.length - 6} yakın yeri daha göster ↓`}
              </Text>
            </Basilabilir>
          ) : null}
        </View>
      ) : null}

      {yakinDurum === "hazir" && yakinlar.length === 0 ? (
        <View style={s.bilgi} accessibilityRole="alert">
          <Text style={s.bilgiBaslik}>Bu çevrede kayıtlı mağaza yok</Text>
          <Text style={s.bilgiYazi}>
            Şube kataloğu şimdilik Kayseri pilotuyla sınırlı — çevrende (~40 km) kayıt bulamadım.
            Mağazayı aşağıdan elle seçince karar yine anında çalışır.
          </Text>
        </View>
      ) : null}

      {manuelGoster ? (
        <View style={s.manuelAlan}>
          <Text style={s.altBaslik}>Mağazayı ara</Text>
          <TextInput
            value={arama}
            onChangeText={setArama}
            placeholder="Migros, BİM, Teknosa…"
            placeholderTextColor={TEMA.renk.yaziEnSoluk}
            style={s.arama}
            autoCorrect={false}
            returnKeyType="search"
            accessibilityLabel="Mağaza ara"
          />
          <View style={s.manuelSonuclar}>
            {sonuclar.map((marka, i) => (
              <GirisSatir key={marka} sira={i} hareketAzalt={hareketAzalt}>
                <Basilabilir
                  onPress={() => {
                    onSec({ marka, subeAd: null, kaynak: "manual" });
                    setArama("");
                    setManuelAcik(false);
                  }}
                  stil={s.manuelSecim}
                  hareketAzalt={hareketAzalt}
                  accessibilityRole="button"
                  accessibilityLabel={`${marka} mağazasını seç`}
                >
                  <Text style={s.manuelSecimYazi}>{marka}</Text>
                  <Text style={s.manuelSecimOk}>›</Text>
                </Basilabilir>
              </GirisSatir>
            ))}
          </View>
          {sonuclar.length === 0 ? (
            <Text style={s.sonucYok}>Bu pilot listede eşleşen mağaza yok.</Text>
          ) : null}
        </View>
      ) : null}
    </View>
  );
}

