/**
 * NE:       Eski kampanya verisini seçili markete göre güvenli bir karar havuzuna dönüştürür.
 * NEDEN:    Yalnız kategoriye bakmak BİM'de Tazemasa'yı, kısmi metin eşleşmesi ise
 *           Migros'ta Migros Hemen kampanyasını kazanan gösterebilir.
 * NASIL:    Seçili işyerini zorunlu tutar; Türkçe metni Unicode/boşluk/büyük-küçük harf
 *           bakımından normalize edip yalnız tam eşitliği kabul eder. İşyeri belirtmeyen
 *           genel kampanyaları silmez, UI'ın belirsizliği gösterebilmesi için category_only
 *           olarak sınıflandırır.
 * YAN ETKİ: Yok; girdileri değiştirmez, IO/ağ/depo erişimi yapmaz ve mevcut motoru çağırmaz.
 */

export interface EskiMarketKampanyasi {
  isyerleri?: readonly string[] | null;
}

export type MarketKapsamSinifi = "merchant_exact" | "category_only";
export type MarketBelirsizligi = "none" | "merchant_not_declared";

export interface MarketGecisAdayi<TKampanya extends EskiMarketKampanyasi> {
  kampanya: TKampanya;
  kapsam: MarketKapsamSinifi;
  belirsizlik: MarketBelirsizligi;
}

export interface MarketGecisSonucu<TKampanya extends EskiMarketKampanyasi> {
  durum: "ready" | "merchant_required";
  seciliIsyeriNormalize: string | null;
  kararHavuzu: MarketGecisAdayi<TKampanya>[];
  elenenKampanyaSayisi: number;
}

/**
 * Türkçe büyük/küçük harf kurallarını korur; aksan veya noktalama işaretlerini silmeyerek
 * farklı marka adlarının yanlışlıkla aynı anahtara dönüşmesini önler.
 */
export function marketIsyeriNormalizeEt(isyeri: string): string {
  return isyeri
    .normalize("NFKC")
    .trim()
    .replace(/\s+/gu, " ")
    .toLocaleLowerCase("tr-TR")
    .normalize("NFC");
}

export function eskiMarketKararHavuzuOlustur<TKampanya extends EskiMarketKampanyasi>(
  kampanyalar: readonly TKampanya[],
  seciliIsyeri: string | null | undefined
): MarketGecisSonucu<TKampanya> {
  const seciliIsyeriNormalize = marketIsyeriNormalizeEt(seciliIsyeri ?? "");

  if (!seciliIsyeriNormalize) {
    return {
      durum: "merchant_required",
      seciliIsyeriNormalize: null,
      kararHavuzu: [],
      elenenKampanyaSayisi: kampanyalar.length,
    };
  }

  const kararHavuzu: MarketGecisAdayi<TKampanya>[] = [];

  for (const kampanya of kampanyalar) {
    const tanimliIsyerleri = (kampanya.isyerleri ?? [])
      .map(marketIsyeriNormalizeEt)
      .filter((isyeri) => isyeri.length > 0);

    if (tanimliIsyerleri.length === 0) {
      kararHavuzu.push({
        kampanya,
        kapsam: "category_only",
        belirsizlik: "merchant_not_declared",
      });
      continue;
    }

    if (tanimliIsyerleri.includes(seciliIsyeriNormalize)) {
      kararHavuzu.push({
        kampanya,
        kapsam: "merchant_exact",
        belirsizlik: "none",
      });
    }
  }

  return {
    durum: "ready",
    seciliIsyeriNormalize,
    kararHavuzu,
    elenenKampanyaSayisi: kampanyalar.length - kararHavuzu.length,
  };
}
