/**
 * NE:       Kart eklendi kutlaması — cüzdana kart eklenince tek-atış altın kutlama overlay'i.
 * NEDEN:    Mehmet abi / arayüz araştırması (Kudos deseni): kart eklemek angarya değil KEYİF olmalı;
 *           "program bir şey yapıyor" hissi anında görünür. İlk kartta özel karşılama (aha), sonrakinde sade onay.
 * NASIL:    Animated yay giriş (scale+fade) + altın halka nabzı + auto-dismiss (~2sn) + başarı haptiği.
 *           İçerik salt sunum; para/motor YOK. reduce-motion'da anında belirir/kapanır (dinginlik).
 * YAN ETKİ: dokunsalBasari cihaz titreşimi; onKapat ile kendini kaldırtır.
 */
import { useEffect, useRef } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import Svg, { Path } from "react-native-svg";
import { TEMA } from "../tema";
import { dokunsalBasari } from "../dokunsal";

export function KartEklendiKutlama({
  sayi,
  hareketAzalt = false,
  onKapat,
}: {
  /** Toplam kart sayısı (1 = ilk kart, özel karşılama) */
  sayi: number;
  hareketAzalt?: boolean;
  onKapat: () => void;
}) {
  const g = useRef(new Animated.Value(hareketAzalt ? 1 : 0)).current;
  const nabiz = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    dokunsalBasari();
    if (hareketAzalt) {
      const t = setTimeout(onKapat, 1400);
      return () => clearTimeout(t);
    }
    Animated.spring(g, { toValue: 1, useNativeDriver: true, ...TEMA.yay.sahne }).start();
    const halka = Animated.loop(
      Animated.sequence([
        Animated.timing(nabiz, { toValue: 1, duration: 900, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
        Animated.timing(nabiz, { toValue: 0, duration: 900, easing: Easing.inOut(Easing.sin), useNativeDriver: true }),
      ]),
    );
    halka.start();
    const t = setTimeout(onKapat, 2100);
    return () => {
      halka.stop();
      clearTimeout(t);
    };
  }, [g, nabiz, hareketAzalt, onKapat]);

  const ilk = sayi <= 1;
  return (
    <Animated.View style={[StyleSheet.absoluteFill, s.kap, { opacity: g }]}>
      <Animated.View
        style={[
          s.kart,
          { transform: [{ scale: g.interpolate({ inputRange: [0, 1], outputRange: [0.86, 1] }) }] },
        ]}
      >
        {/* Altın nabız halkası + madalyon */}
        <View style={s.madalyonSar}>
          <Animated.View
            style={[
              s.nabizHalka,
              {
                opacity: nabiz.interpolate({ inputRange: [0, 1], outputRange: [0.5, 0] }),
                transform: [{ scale: nabiz.interpolate({ inputRange: [0, 1], outputRange: [1, 1.5] }) }],
              },
            ]}
          />
          <LinearGradient
            colors={[TEMA.renk.altin, TEMA.renk.altinAcik]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.madalyon}
          >
            <Svg width={34} height={34} viewBox="0 0 24 24" fill="none">
              <Path d="M5 13l4 4L19 7" stroke={TEMA.renk.zeminKoyu} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
            </Svg>
          </LinearGradient>
        </View>
        <Text style={s.baslik}>{ilk ? "İlk kartın eklendi! 🎉" : "Kartın cüzdanına eklendi"}</Text>
        <Text style={s.alt}>
          {ilk
            ? "Artık sana bu kartla en kârlı ödemeyi söyleyebilirim."
            : `Cüzdanında ${sayi} kart · daha isabetli kararlar`}
        </Text>
      </Animated.View>
    </Animated.View>
  );
}

const s = StyleSheet.create({
  kap: { backgroundColor: "rgba(8,10,13,0.72)", alignItems: "center", justifyContent: "center", zIndex: 50 },
  kart: {
    width: "82%",
    maxWidth: 360,
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    backgroundColor: TEMA.yuzey.kazanan.zemin,
    paddingVertical: TEMA.bosluk.xl,
    paddingHorizontal: TEMA.bosluk.l,
    alignItems: "center",
    gap: TEMA.bosluk.s,
  },
  madalyonSar: { width: 72, height: 72, alignItems: "center", justifyContent: "center", marginBottom: TEMA.bosluk.s },
  nabizHalka: {
    position: "absolute",
    width: 72,
    height: 72,
    borderRadius: 36,
    borderWidth: 2,
    borderColor: TEMA.renk.altinKenar,
  },
  madalyon: { width: 60, height: 60, borderRadius: 30, alignItems: "center", justifyContent: "center" },
  baslik: { color: TEMA.renk.yazi, fontSize: 18, fontWeight: "900", textAlign: "center", letterSpacing: -0.2 },
  alt: { color: TEMA.renk.yaziSoluk, fontSize: 13, textAlign: "center", lineHeight: 18 },
});
