/**
 * NE:       Karar ekranı mağaza teyit hero şeridi — "neredesin?" sorusuna GÖRSEL cevap.
 * NEDEN:    Görsel devrim planı Faz 3: mağaza teyidi minik metin satırı değil, o mağazanın kategori
 *           SAHNESİ + logosuyla premium bir sahne olmalı (Maximum/banka app'lerinin karar-öncesi hissi).
 * NASIL:    KategoriGorsel(kategori, ~92) sahne + çift scrim + üst okunurluk şeridi + beyaz mağaza logosu
 *           (yoksa ad) + şube/konum satırı. Kategori App'in markadan türettiği `kategori` state'inden gelir.
 * YAN ETKİ: Yok — saf sunum; görsel yoksa KategoriGorsel premium fallback'e düşer (çökme yok).
 */
import { Image, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { magazaLogo, magazaRenk } from "../marka/magazaLogolari";
import { hexA } from "../marka/markalar";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";

const HERO = 92;

export function MagazaHero({
  marka,
  subeAd,
  kaynak,
  onDegistir,
}: {
  marka: string;
  subeAd: string | null;
  kaynak: "location" | "manual";
  /** Verilirse "✓ buradasın" yerine "Değiştir" butonu gösterilir (seçili mağaza kartı olarak kullanım) */
  onDegistir?: () => void;
}) {
  /*
   * NE: Marka rengi hero'sunda kullanılmayan eski `kategori` girdisini sözleşmeden çıkarır.
   * NEDEN: Hero kategori görselinden marka kimliğine geçti; ölü prop kalite kapısını durduruyordu.
   * NASIL: Bileşen yalnız marka, şube, kaynak ve değiştirme eylemini kabul eder.
   * YAN ETKİ: Mağaza görseli ve seçim davranışı değişmez.
   */
  const logo = magazaLogo(marka);
  const renk = magazaRenk(marka);
  return (
    <View style={s.kap}>
      {/* Mağaza marka rengi zemin — her mağaza kendi kimliğiyle (kategori sahne tekrarı yerine) */}
      <LinearGradient
        colors={[hexA(renk, 0.92), hexA(renk, 0.58), hexA(renk, 0.32)]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      <LinearGradient
        colors={["rgba(255,255,255,0.12)", "transparent"]}
        start={{ x: 0.3, y: 0 }}
        end={{ x: 0.7, y: 1 }}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      {/* Alt: grafite yumuşak geçiş (satırdan kopmasın) */}
      <LinearGradient
        colors={["transparent", hexA(TEMA.renk.zemin, 0.35)]}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      <View style={s.icerik}>
        {logo ? (
          <Image source={logo} style={s.logo} resizeMode="contain" accessibilityLabel={marka} />
        ) : (
          <View style={s.markaNokta} />
        )}
        <View style={s.bilgi}>
          <Text style={s.markaAd} numberOfLines={1}>
            {marka}
          </Text>
          <Text style={s.sube} numberOfLines={1}>
            {subeAd ?? (kaynak === "location" ? "yakınındaki şube" : "elle seçildin")}
          </Text>
        </View>
        {onDegistir ? (
          <Basilabilir
            onPress={onDegistir}
            stil={s.degistir}
            accessibilityRole="button"
            accessibilityLabel="Seçili mağazayı değiştir"
          >
            <Text style={s.degistirYazi}>Değiştir</Text>
          </Basilabilir>
        ) : (
          <View style={s.teyit}>
            <Text style={s.teyitYazi}>✓ buradasın</Text>
          </View>
        )}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  kap: {
    height: HERO,
    borderRadius: TEMA.yaricap.orta,
    overflow: "hidden",
    borderWidth: 1,
    borderColor: TEMA.yuzey.kat1.kenar,
    marginBottom: TEMA.bosluk.m,
    justifyContent: "flex-end",
  },
  ustSerit: { position: "absolute", top: 0, left: 0, right: 0, height: 44 },
  icerik: { flexDirection: "row", alignItems: "center", gap: TEMA.bosluk.m, padding: TEMA.bosluk.m },
  logo: { width: 44, height: 26 },
  markaNokta: { width: 10, height: 10, borderRadius: 5, backgroundColor: TEMA.renk.gumus },
  bilgi: { flex: 1 },
  markaAd: {
    color: "#fff",
    fontSize: 15,
    fontWeight: "800",
    textShadowColor: "rgba(0,0,0,0.5)",
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 3,
  },
  sube: { color: "rgba(255,255,255,0.8)", fontSize: 11.5, marginTop: 1 },
  teyit: {
    borderRadius: TEMA.yaricap.hap,
    backgroundColor: "rgba(0,0,0,0.5)",
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    paddingHorizontal: 10,
    paddingVertical: 4,
  },
  teyitYazi: { color: TEMA.renk.altinAcik, fontSize: 11, fontWeight: "700" },
  degistir: {
    borderRadius: TEMA.yaricap.hap,
    backgroundColor: "rgba(0,0,0,0.5)",
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    paddingHorizontal: 14,
    paddingVertical: 7,
  },
  degistirYazi: { color: TEMA.renk.altinAcik, fontSize: 12.5, fontWeight: "700" },
});
