/**
 * NE:       Android ve iPhone'da kullanıcı ile en yakın altı mağazayı gerçek yerel yol haritasında gösterir.
 * NEDEN:    Kullanıcı bulunduğu mevkiyi ve mağazaların yönünü ayrı bir uygulamaya geçmeden, gerçek yollar üzerinde
 *           tek bakışta ayırt edebilmelidir.
 * NASIL:    react-native-maps ile Android'de Google Maps, iOS'ta Apple Maps kullanır; saf kapsam motorunun verdiği
 *           bölgeye kullanıcı işareti ve listeyle eşleşen 1–6 marka renkli mağaza işareti yerleştirir.
 * YAN ETKİ: Harita karoları platform harita sağlayıcısından gelir ve sağlayıcıya yaklaşık görünüm bölgesi iletilir;
 *           KartAkıl konumu saklamaz. Native bağımlılık nedeniyle mevcut eski APK'ya OTA ile eklenemez, yeni build gerekir.
 */
import { useMemo } from "react";
import { Platform, StyleSheet, Text, View } from "react-native";
import MapView, { Marker, PROVIDER_GOOGLE } from "react-native-maps";
import { magazaRenk } from "../marka/magazaLogolari";
import {
  gercekHaritaKapsamiOlustur,
  type KullaniciKonumu,
} from "../motor/gercekHarita";
import type { YakinMagaza } from "../motor/konum";
import { gercekHaritaAc } from "../veri/haritaKopru";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";
import { GercekHaritaYedegi } from "./GercekHaritaYedegi";

type Props = {
  konum: KullaniciKonumu;
  yakinlar: readonly YakinMagaza[];
};

export function YakinCevreHaritasi({ konum, yakinlar }: Props) {
  const kapsam = useMemo(
    () => gercekHaritaKapsamiOlustur(konum, yakinlar),
    [konum, yakinlar]
  );
  const haritaAnahtari = kapsam
    ? `${konum.lat}:${konum.lon}:${kapsam.noktalar.map((nokta) => `${nokta.lat}:${nokta.lon}`).join("|")}`
    : "gecersiz";

  if (!kapsam) return <GercekHaritaYedegi konum={konum} yakinlar={yakinlar} />;

  return (
    <View style={s.kap}>
      <View style={s.haritaCerçevesi}>
        <MapView
          key={haritaAnahtari}
          style={StyleSheet.absoluteFill}
          provider={Platform.OS === "android" ? PROVIDER_GOOGLE : undefined}
          mapType="standard"
          initialRegion={{
            latitude: kapsam.merkez.lat,
            longitude: kapsam.merkez.lon,
            latitudeDelta: kapsam.latitudeDelta,
            longitudeDelta: kapsam.longitudeDelta,
          }}
          showsUserLocation={false}
          showsMyLocationButton={false}
          showsCompass
          showsBuildings
          showsPointsOfInterests
          toolbarEnabled={false}
          accessibilityLabel={`Gerçek yakın çevre haritası. Sen ve en yakın ${kapsam.noktalar.length} yer gösteriliyor.`}
        >
          <Marker
            coordinate={{ latitude: konum.lat, longitude: konum.lon }}
            title="Sen buradasın"
            description="Mevcut konumun"
            tracksViewChanges={false}
          >
            <View style={s.kullaniciDis}>
              <View style={s.kullaniciIc} />
            </View>
          </Marker>
          {kapsam.noktalar.map((nokta) => (
            <Marker
              key={`${nokta.sira}-${nokta.marka}-${nokta.subeAd}`}
              coordinate={{ latitude: nokta.lat, longitude: nokta.lon }}
              title={`${nokta.sira}. ${nokta.marka}`}
              description={nokta.subeAd}
              tracksViewChanges={false}
            >
              <View style={[s.magazaIsareti, { backgroundColor: magazaRenk(nokta.marka) }]}>
                <Text style={s.magazaNo}>{nokta.sira}</Text>
              </View>
              <View style={[s.isaretUcu, { borderTopColor: magazaRenk(nokta.marka) }]} />
            </Marker>
          ))}
        </MapView>

        <View style={s.ustBilgi} pointerEvents="none">
          <Text style={s.baslik}>Gerçek yakın çevre</Text>
          <Text style={s.alt}>Mavi nokta sensin · 1–{kapsam.noktalar.length} aşağıdaki yerlerle eşleşir</Text>
        </View>
      </View>

      <Basilabilir
        onPress={() => gercekHaritaAc(konum)}
        stil={s.buyut}
        accessibilityRole="link"
        accessibilityLabel="Gerçek haritayı harita uygulamasında büyüt"
      >
        <Text style={s.buyutYazi}>Haritada büyüt ↗</Text>
      </Basilabilir>
      <Text style={s.gizlilik}>Gerçek yol haritası · konumun KartAkıl’da saklanmaz</Text>
    </View>
  );
}

const s = StyleSheet.create({
  kap: {
    borderRadius: TEMA.yaricap.buyuk,
    borderWidth: 1,
    borderColor: "rgba(75,164,255,0.32)",
    backgroundColor: "rgba(16,23,34,0.92)",
    padding: 6,
    gap: 7,
    overflow: "hidden",
  },
  haritaCerçevesi: {
    height: 268,
    borderRadius: 18,
    overflow: "hidden",
    backgroundColor: "#d8dde3",
  },
  ustBilgi: {
    position: "absolute",
    top: 9,
    left: 9,
    right: 9,
    borderRadius: 14,
    borderWidth: 1,
    borderColor: "rgba(255,255,255,0.2)",
    backgroundColor: "rgba(13,17,23,0.88)",
    paddingHorizontal: 12,
    paddingVertical: 9,
  },
  baslik: { color: TEMA.renk.yazi, fontSize: 13, fontWeight: "900" },
  alt: { color: "#c2cad5", fontSize: 9.5, lineHeight: 13, marginTop: 2 },
  kullaniciDis: {
    width: 25,
    height: 25,
    borderRadius: 13,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(75,164,255,0.22)",
    borderWidth: 2,
    borderColor: "#ffffff",
  },
  kullaniciIc: {
    width: 11,
    height: 11,
    borderRadius: 6,
    backgroundColor: "#318ce7",
  },
  magazaIsareti: {
    width: 31,
    height: 31,
    borderRadius: 16,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 2,
    borderColor: "#ffffff",
  },
  magazaNo: { color: "#ffffff", fontSize: 12, fontWeight: "900" },
  isaretUcu: {
    alignSelf: "center",
    marginTop: -2,
    width: 0,
    height: 0,
    borderLeftWidth: 5,
    borderRightWidth: 5,
    borderTopWidth: 7,
    borderLeftColor: "transparent",
    borderRightColor: "transparent",
  },
  buyut: {
    minHeight: 44,
    borderRadius: 14,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(75,164,255,0.13)",
    borderWidth: 1,
    borderColor: "rgba(75,164,255,0.36)",
  },
  buyutYazi: { color: "#acd8ff", fontSize: 12, fontWeight: "800" },
  gizlilik: { color: TEMA.renk.yaziEnSoluk, fontSize: 9.5, textAlign: "center", paddingBottom: 3 },
});
