/**
 * NE:       Bir harita servisinden (Google Places) gelen ham işletme adını bizim BİLİNEN markaya eşler.
 * NEDEN:    Places "Migros 5M Kayseri", "ŞOK Market", "BİM Birleşik Mağazalar" gibi serbest adlar döndürür;
 *           KartAkıl yalnız kampanyası olan (MARKA_KATEGORI'deki) markaları göstermeli — alakasız bakkal değil.
 * NASIL:    Türkçe-güvenli normalize (İ/ı, aksan) + "en uzun eşleşen marka" kuralı (A101'i "101"e, Petrol
 *           Ofisi'ni "Opet"e kaptırmamak için uzun anahtar öncelikli). Saf fonksiyon — ağsız, test edilebilir.
 * YAN ETKİ: Yok.
 */
export function markaAnahtari(deger: string): string {
  return (deger ?? "")
    .toLocaleLowerCase("tr-TR")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/gu, "")
    .replace(/ı/gu, "i")
    .replace(/[^a-z0-9]+/gu, " ")
    .trim();
}

/**
 * Places adını bilinen markalardan birine eşler; eşleşme yoksa null.
 * `markalar` = MARKA_KATEGORI anahtarları (App'ten geçilir; kod marka adı hardcode etmez).
 */
export function markaTani(placesAdi: string, markalar: readonly string[]): string | null {
  const ad = ` ${markaAnahtari(placesAdi)} `;
  if (ad.trim().length === 0) return null;

  let bulunan: string | null = null;
  let enUzun = 0;
  for (const marka of markalar) {
    const anahtar = markaAnahtari(marka);
    if (anahtar.length < 2) continue;
    // TAM SÖZCÜK eşleşme (ad iki yandan boşlukla sarılı): "Migros" eşleşir, "Migroskop" eşleşmez.
    const gecer = ad.includes(` ${anahtar} `);
    if (gecer && anahtar.length > enUzun) {
      bulunan = marka;
      enUzun = anahtar.length;
    }
  }
  return bulunan;
}
