/**
 * NE:       Nöbetçi eczane servisi — Supabase'den bugünün canlı verisi (gece robotu besler) → yoksa
 *           bugünün seed verisi (nobetci-eczane-kayseri.json, fallback). Asla boş kalmaz.
 * NEDEN:    Nöbetçi eczane HER GÜN değişir. NosyAPI panelde abonelik/kredi istiyordu (Mehmet abi'yi
 *           uğraştırıyor) → BIRAKILDI. Yerine: kendi robotumuz (eczaneler.gen.tr) her gün çekip
 *           Supabase'e yazar; uygulama Supabase'den okur (kredi yok, tam kontrol bizde).
 * NASIL:    Supabase REST (anon key, il=Kayseri) → başarı canlı; ağ/boş → seed fallback.
 * YAN ETKİ: Yalnız İL ADI ("Kayseri") sorgulanır — GPS/konum GÖNDERİLMEZ (kırmızı çizgi #4 korunur).
 *           Asla exception fırlatmaz; her dalda geçerli bir sonuç döner.
 */
import seed from "./nobetci-eczane-kayseri.json";

const SB_URL = process.env.EXPO_PUBLIC_SUPABASE_URL;
const SB_ANON = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY;
const IL = "Kayseri";

export interface NobetciEczane {
  ad: string;
  adres: string;
  ilce: string;
  tel: string;
  not?: string;
  /** Konum (seed'de geocode ile, NosyAPI'de canlı) — en yakını sıralamak için; yoksa mesafesiz gösterilir. */
  lat?: number;
  lon?: number;
}
export interface NobetciSonuc {
  tarih: string;
  eczaneler: NobetciEczane[];
  /** true = NosyAPI'den bugünün canlı verisi · false = seed fallback (elle çekilen son gün) */
  canli: boolean;
}

const SEED: NobetciSonuc = {
  tarih: (seed as { tarih?: string }).tarih ?? "",
  eczaneler: ((seed as { eczaneler?: NobetciEczane[] }).eczaneler ?? []) as NobetciEczane[],
  canli: false,
};

export async function nobetciEczaneler(zamanAsimiMs = 6000): Promise<NobetciSonuc> {
  if (!SB_URL || !SB_ANON) return SEED; // yapılandırma yoksa: bugünün seed'i

  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), zamanAsimiMs);
    const res = await fetch(
      `${SB_URL}/rest/v1/nobetci_eczane?il=eq.${encodeURIComponent(IL)}&select=tarih,eczaneler`,
      { headers: { apikey: SB_ANON, Authorization: `Bearer ${SB_ANON}` }, signal: ctrl.signal }
    );
    clearTimeout(t);
    if (!res.ok) return SEED;

    const d: unknown = await res.json();
    const satir = Array.isArray(d) ? (d[0] as { tarih?: string; eczaneler?: unknown } | undefined) : undefined;
    const ham = Array.isArray(satir?.eczaneler) ? (satir!.eczaneler as unknown[]) : [];
    const eczaneler: NobetciEczane[] = ham
      .map((x) => {
        const r = x as Record<string, unknown>;
        const lat = Number(r.lat ?? r.latitude);
        const lon = Number(r.lon ?? r.longitude ?? r.lng);
        return {
          ad: String(r.ad ?? r.name ?? "").trim(),
          adres: String(r.adres ?? r.address ?? "").trim(),
          ilce: String(r.ilce ?? r.district ?? "").trim(),
          tel: String(r.tel ?? r.phone ?? "").trim(),
          not: typeof r.not === "string" ? r.not : undefined,
          lat: Number.isFinite(lat) ? lat : undefined,
          lon: Number.isFinite(lon) ? lon : undefined,
        };
      })
      .filter((e) => e.ad.length > 0 && e.tel.length > 0);

    if (eczaneler.length === 0) return SEED;
    return { tarih: satir?.tarih ?? new Date().toISOString().slice(0, 10), eczaneler, canli: true };
  } catch {
    return SEED; // ağ/timeout/parse → seed fallback
  }
}
