/**
 * NE:       Web'de PWA kurulumunu kolaylaştıran, web ve native'de uygulanan güncellemeyi görünür kılan alt banner.
 * NEDEN:    Mehmet abi: "arkadaşlarım hiç uğraşmadan eklesin." Tarayıcı otomatik eklemeye
 *           izin vermez (güvenlik) → az-sürtünmeli köprü: Android'de tek-tık 'Yükle',
 *           iPhone'da 'Paylaş → Ana Ekrana Ekle' rehberi. Native app'te yalnız yeni EAS Update sonrası bir kez görünür.
 * NASIL:    Platform.OS==='web' guard. Android: beforeinstallprompt event yakalanır → Yükle
 *           butonu prompt() çağırır. iOS Safari: event yok → statik rehber kutusu. Zaten
 *           standalone (ana ekrandan) açıldıysa veya kullanıcı kapattıysa (localStorage) gösterilmez.
 * YAN ETKİ: Service worker kaydı (installability + offline kabuk + görünür sürüm bildirimi).
 *            localStorage yalnız PWA kurulum tercihini, AsyncStorage yalnız görülen native update kimliğini saklar.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useEffect, useRef, useState } from "react";
import { Animated, Platform, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import * as Updates from "expo-updates";
import Svg, { Path } from "react-native-svg";
import { duyurulacakNativeGuncellemeKimligi } from "../motor/guncellemeDuyurusu";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";

const KAPATILDI = "kartakil-pwa-kapatildi";
const SON_GORULEN_NATIVE_GUNCELLEME = "kartakil-son-gorulen-native-guncelleme";
// Pages proje yolu (baseUrl ile aynı) — service worker kapsamı için
const TABAN = "/kart-akil-indir";

export function AnaEkranaEkle() {
  const [mod, setMod] = useState<"yok" | "ios" | "android" | "guncelle" | "native-guncellendi">("yok");
  const promptRef = useRef<any>(null);
  const nativeGuncellemeRef = useRef<string | null>(null);
  const gir = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (Platform.OS !== "web" || typeof window === "undefined") return;
    const w = window as any;
    // Ana ekrandan açılan uygulama kurulum yardımını görmez; güncelleme kontrolünü yine çalıştırır.
    const standalone =
      w.matchMedia?.("(display-mode: standalone)")?.matches || w.navigator?.standalone === true;
    let kurulumYardimcisiKapali = standalone;
    try {
      kurulumYardimcisiKapali ||= w.localStorage?.getItem(KAPATILDI) === "1";
    } catch {}

    /*
     * NE: Yeni PWA worker'ını algılayıp kullanıcıya tek, görünür "Yeni sürümü aç" kararı verir.
     * NEDEN: Ağ-öncelikli güncelleme teknik olarak gelse bile arkadaşlar hangi sürümü gördüğünü anlayamıyordu.
     * NASIL: Önceden controller varsa waiting/installing/controllerchange sinyallerinden herhangi biri bildirimi açar.
     * YAN ETKİ: İlk service worker kurulumu güncelleme sayılmaz; ana ekran kurulum yardımcısı davranışı korunur.
     */
    let controllerDegisti: (() => void) | undefined;
    try {
      if ("serviceWorker" in w.navigator) {
        const oncekiControllerVar = Boolean(w.navigator.serviceWorker.controller);
        controllerDegisti = () => {
          if (oncekiControllerVar) setMod("guncelle");
        };
        w.navigator.serviceWorker.addEventListener("controllerchange", controllerDegisti);
        w.navigator.serviceWorker
          .register(`${TABAN}/sw.js`, { scope: `${TABAN}/` })
          .then((kayit: any) => {
            if (kayit.waiting && oncekiControllerVar) setMod("guncelle");
            kayit.addEventListener("updatefound", () => {
              const yeniWorker = kayit.installing;
              yeniWorker?.addEventListener("statechange", () => {
                if (yeniWorker.state === "installed" && oncekiControllerVar) setMod("guncelle");
              });
            });
            kayit.update?.().catch(() => {});
          })
          .catch(() => {});
      }
    } catch {}

    const ua = w.navigator?.userAgent || "";
    const ios = /iphone|ipad|ipod/i.test(ua);
    const safari = /safari/i.test(ua) && !/crios|fxios|edgios/i.test(ua);

    let zamanlayici: ReturnType<typeof setTimeout> | undefined;
    const onPrompt = (e: any) => {
      e.preventDefault(); // Chrome'un kendi çubuğunu bastır, kendi butonumuzu göster
      promptRef.current = e;
      if (!kurulumYardimcisiKapali) setMod("android");
    };
    w.addEventListener("beforeinstallprompt", onPrompt);

    // iOS Safari: beforeinstallprompt yok → kısa gecikmeyle nazik rehber (uygulamayı bir tanısın)
    if (!kurulumYardimcisiKapali && ios && safari) {
      zamanlayici = setTimeout(() => setMod("ios"), 2600);
    }

    return () => {
      w.removeEventListener("beforeinstallprompt", onPrompt);
      if (controllerDegisti) {
        w.navigator.serviceWorker?.removeEventListener("controllerchange", controllerDegisti);
      }
      if (zamanlayici) clearTimeout(zamanlayici);
    };
  }, []);

  useEffect(() => {
    /*
     * NE: Uygulanan EAS Update'i Android/iPhone kullanıcısına yalnız bir kez görünür kılar.
     * NEDEN: OTA sessiz uygulanırsa arkadaş hangi sürümü kullandığını ve yeniliğin geldiğini anlayamaz.
     * NASIL: Embedded pakette çalışmaz; EAS updateId daha önce görülmediyse kimliği ref'te tutup native banner'ı açar.
     * YAN ETKİ: Güncelleme içeriği veya indirme davranışı değişmez; yalnız cihazda son görülen updateId saklanır.
     */
    if (Platform.OS === "web" || Updates.isEmbeddedLaunch || !Updates.updateId) return;
    let iptal = false;
    const guncellemeyiDuyur = async () => {
      try {
        const sonGorulen = await AsyncStorage.getItem(SON_GORULEN_NATIVE_GUNCELLEME);
        const duyurulacakKimlik = duyurulacakNativeGuncellemeKimligi(
          Platform.OS,
          Updates.isEmbeddedLaunch,
          Updates.updateId,
          sonGorulen,
        );
        if (!iptal && duyurulacakKimlik) {
          nativeGuncellemeRef.current = duyurulacakKimlik;
          setMod("native-guncellendi");
        }
      } catch {
        // Yerel tercih okunamazsa güncellemeyi gizlemek yerine kullanıcıya göster.
        const duyurulacakKimlik = duyurulacakNativeGuncellemeKimligi(
          Platform.OS,
          Updates.isEmbeddedLaunch,
          Updates.updateId,
          null,
        );
        if (!iptal && duyurulacakKimlik) {
          nativeGuncellemeRef.current = duyurulacakKimlik;
          setMod("native-guncellendi");
        }
      }
    };
    void guncellemeyiDuyur();
    return () => {
      iptal = true;
    };
  }, []);

  useEffect(() => {
    if (mod !== "yok") {
      Animated.spring(gir, { toValue: 1, useNativeDriver: true, ...TEMA.yay.nazik }).start();
    }
  }, [mod, gir]);

  if (mod === "yok") return null;
  const guncellemeModu = mod === "guncelle" || mod === "native-guncellendi";

  const kapat = () => {
    if (mod === "ios" || mod === "android") {
      try {
        (window as any).localStorage?.setItem(KAPATILDI, "1");
      } catch {}
    }
    if (mod === "native-guncellendi" && nativeGuncellemeRef.current) {
      void AsyncStorage.setItem(SON_GORULEN_NATIVE_GUNCELLEME, nativeGuncellemeRef.current).catch(() => {});
    }
    Animated.timing(gir, { toValue: 0, duration: 200, useNativeDriver: true }).start(() => setMod("yok"));
  };

  const yukle = async () => {
    const p = promptRef.current;
    if (!p) return;
    p.prompt();
    try {
      await p.userChoice;
    } catch {}
    promptRef.current = null;
    kapat();
  };

  const yeniSurumuAc = () => {
    if (typeof window !== "undefined") window.location.reload();
  };

  return (
    <Animated.View
      style={[
        s.kap,
        { opacity: gir, transform: [{ translateY: gir.interpolate({ inputRange: [0, 1], outputRange: [90, 0] }) }] },
      ]}
      pointerEvents="box-none"
    >
      <View style={s.banner}>
        <View style={s.ikonSar}>
          <LinearGradient
            colors={[TEMA.renk.altin, TEMA.renk.altinAcik]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.ikon}
          >
            <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
              <Path
                d="M12 15V3M12 15l-4-4M12 15l4-4M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2"
                stroke={TEMA.renk.zeminKoyu}
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </LinearGradient>
        </View>
        <View style={s.metin}>
          <Text style={s.baslik}>
            {guncellemeModu ? "KartAkıl güncellendi" : "KartAkıl'ı ana ekranına ekle"}
          </Text>
          {guncellemeModu ? (
            <Text style={s.alt}>
              {mod === "native-guncellendi"
                ? "Yeni özellikler ve düzeltmeler kullanıma hazır"
                : "Yeni özellikler ve düzeltmeler hazır"}
            </Text>
          ) : mod === "android" ? (
            <Text style={s.alt}>Uygulama gibi tek dokunuşta açılsın</Text>
          ) : (
            <Text style={s.alt}>
              Paylaş <Text style={s.vurgu}>⬆︎</Text> → <Text style={s.vurgu}>Ana Ekrana Ekle</Text>
            </Text>
          )}
        </View>
        {mod === "guncelle" ? (
          <Basilabilir
            onPress={yeniSurumuAc}
            stil={s.yukleBtn}
            accessibilityRole="button"
            accessibilityLabel="KartAkıl'ın yeni sürümünü aç"
          >
            <Text style={s.yukleYazi}>Yeni sürümü aç</Text>
          </Basilabilir>
        ) : mod === "native-guncellendi" ? (
          <Basilabilir
            onPress={kapat}
            stil={s.yukleBtn}
            accessibilityRole="button"
            accessibilityLabel="KartAkıl güncelleme bildirimini onayla"
          >
            <Text style={s.yukleYazi}>Tamam</Text>
          </Basilabilir>
        ) : mod === "android" ? (
          <Basilabilir onPress={yukle} stil={s.yukleBtn} accessibilityRole="button" accessibilityLabel="Uygulamayı yükle">
            <Text style={s.yukleYazi}>Yükle</Text>
          </Basilabilir>
        ) : null}
        <Basilabilir onPress={kapat} stil={s.kapatBtn} hitSlop={10} accessibilityRole="button" accessibilityLabel="Kapat">
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
            <Path d="M6 6l12 12M18 6L6 18" stroke={TEMA.renk.yaziSoluk} strokeWidth="2" strokeLinecap="round" />
          </Svg>
        </Basilabilir>
      </View>
    </Animated.View>
  );
}

const s = StyleSheet.create({
  kap: {
    position: "absolute",
    left: 0,
    right: 0,
    bottom: 0,
    paddingHorizontal: TEMA.bosluk.m,
    paddingBottom: TEMA.bosluk.l,
    zIndex: 60,
    alignItems: "center",
  },
  banner: {
    flexDirection: "row",
    alignItems: "center",
    gap: TEMA.bosluk.m,
    width: "100%",
    maxWidth: 480,
    backgroundColor: "rgba(20,23,30,0.97)",
    borderWidth: 1,
    borderColor: TEMA.renk.altinKenar,
    borderRadius: TEMA.yaricap.buyuk,
    paddingVertical: TEMA.bosluk.m,
    paddingHorizontal: TEMA.bosluk.l,
    ...(Platform.OS === "web" ? ({ boxShadow: "0 10px 30px rgba(0,0,0,0.5)" } as object) : {}),
  },
  ikonSar: { width: 40, height: 40 },
  ikon: { width: 40, height: 40, borderRadius: 11, alignItems: "center", justifyContent: "center" },
  metin: { flex: 1, gap: 2 },
  baslik: { color: TEMA.renk.yazi, fontSize: 14, fontWeight: "800", letterSpacing: -0.2 },
  alt: { color: TEMA.renk.yaziSoluk, fontSize: 12 },
  vurgu: { color: TEMA.renk.altinAcik, fontWeight: "700" },
  yukleBtn: {
    backgroundColor: TEMA.renk.altin,
    borderRadius: TEMA.yaricap.hap,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
  yukleYazi: { color: TEMA.renk.zeminKoyu, fontSize: 13, fontWeight: "900" },
  kapatBtn: { padding: 4 },
});
