/**
 * NE:       Yakınımda motorunun cihaz konumu kapısı ve geriye uyumlu hesap dışa aktarımları.
 * NEDEN:    Konum hiçbir uygulama sunucusuna gitmemeli; reddedilmiş izin tekrar zorlanmamalı ve
 *           bozuk platform koordinatı kullanıcıya yanlış mağaza sonucu üretememeli.
 * NASIL:    Web'de tarayıcının tek seferlik geolocation API'sini, native'de yalnız ön plan
 *           expo-location iznini kullanır; saf hesaplar konumHesap modülünden aynen dışa aktarılır.
 * YAN ETKİ: Kullanıcı açıkça yakın mağaza istediğinde sistem ön plan konum diyaloğu açılabilir;
 *           arka plan konumu, uygulama ağı, kalıcı konum kaydı veya izleme başlatılmaz.
 */
import * as Location from "expo-location";
import { Platform } from "react-native";
import { koordinatGecerliMi, onPlanKonumIzniIstenmeliMi } from "./konumHesap";

export { enYakinMagazalar, mesafeM, mesafeYaz } from "./konumHesap";
export type { Sube, YakinMagaza } from "./konumHesap";

function gecerliKonum(lat: number, lon: number): { lat: number; lon: number } | null {
  return koordinatGecerliMi(lat, lon) ? { lat, lon } : null;
}

/** Konumu al — izin reddedilirse veya alınamazsa null (UI nazikçe söyler) */
export async function konumAl(): Promise<{ lat: number; lon: number } | null> {
  try {
    if (Platform.OS === "web") {
      if (typeof navigator === "undefined" || !navigator.geolocation) return null;

      return await new Promise((resolve) => {
        navigator.geolocation.getCurrentPosition(
          (p) => resolve(gecerliKonum(p.coords.latitude, p.coords.longitude)),
          () => resolve(null),
          { enableHighAccuracy: false, timeout: 10000, maximumAge: 60000 }
        );
      });
    }

    const mevcutIzin = await Location.getForegroundPermissionsAsync();
    const izin = onPlanKonumIzniIstenmeliMi(mevcutIzin.granted, mevcutIzin.canAskAgain)
      ? await Location.requestForegroundPermissionsAsync()
      : mevcutIzin;
    if (!izin.granted) return null;

    const konum = await Location.getCurrentPositionAsync({
      accuracy: Location.Accuracy.Balanced,
    });
    return gecerliKonum(konum.coords.latitude, konum.coords.longitude);
  } catch {
    return null;
  }
}
