/**
 * NE:       Mağaza rozeti — mağazanın KENDİ renk kimliğiyle bütünleşik logo+isim
 * NEDEN:    Mehmet abi ilkesi: "logoyu beyaz kutuya yapıştırıp koyma; marka kendi
 *           sekmesiyle BÜTÜNLEŞMELİ" — çip mağazanın rengine bürünür, logo o renkle kaynaşır
 * NASIL:    Zemin = marka renginin hafif tonu, kenar = daha koyu tonu; logo yuvarlak
 *           madalyonda (kutu değil), isim marka renginin okunur tonunda. Markanın
 *           renginden bir "sol vurgu şeridi" ile kimlik pekişir.
 * YAN ETKİ: Yok
 */
import { Image, StyleSheet, Text, View } from "react-native";
import { magazaLogo, magazaRenk } from "../marka/magazaLogolari";
import { hexA } from "../marka/markalar";
import { TEMA } from "../tema";

interface Props {
  marka: string;
  altYazi?: string;
  secili?: boolean;
  boy?: "kucuk" | "orta";
}

/** Koyu grafit zeminde marka renginin okunur (açık) tonu */
function acikTon(hex: string): string {
  const t = hex.replace("#", "");
  let r = parseInt(t.slice(0, 2), 16);
  let g = parseInt(t.slice(2, 4), 16);
  let b = parseInt(t.slice(4, 6), 16);
  // Çok koyu marka renklerini (siyah/lacivert) grafit zeminde görünür yap
  const parlaklik = (r * 299 + g * 587 + b * 114) / 1000;
  if (parlaklik < 90) {
    const k = 2.2;
    r = Math.min(255, Math.round(r * k + 90));
    g = Math.min(255, Math.round(g * k + 90));
    b = Math.min(255, Math.round(b * k + 90));
  }
  return `rgb(${r},${g},${b})`;
}

export function MagazaRozeti({ marka, altYazi, secili, boy = "orta" }: Props) {
  const logo = magazaLogo(marka);
  const renk = magazaRenk(marka);
  const isimRengi = acikTon(renk);
  const madalyon = boy === "kucuk" ? 22 : 28;

  return (
    <View
      style={[
        s.kap,
        {
          backgroundColor: hexA(renk, secili ? 0.26 : 0.14),
          borderColor: hexA(renk, secili ? 0.7 : 0.4),
        },
      ]}
    >
      {/* Marka rengi sol vurgu — kimlik şeridi */}
      <View style={[s.serit, { backgroundColor: renk }]} />
      {logo ? (
        // Beyaz/ters logo doğrudan marka-renkli çipte — kutu/madalyon YOK (o pencereye adaptif)
        <Image
          source={logo}
          style={{ width: madalyon * 2, height: madalyon * 0.8 }}
          resizeMode="contain"
          accessibilityLabel={marka}
        />
      ) : (
        <View style={[s.nokta, { backgroundColor: renk }]} />
      )}
      <View style={s.metin}>
        <Text style={[s.isim, { color: isimRengi }, boy === "kucuk" && s.isimKucuk]} numberOfLines={1}>
          {marka}
        </Text>
        {altYazi && <Text style={s.alt}>{altYazi}</Text>}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  kap: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    borderRadius: TEMA.yaricap.orta,
    borderWidth: 1,
    paddingVertical: 6,
    paddingHorizontal: 10,
    paddingLeft: 12,
    overflow: "hidden",
  },
  serit: { position: "absolute", left: 0, top: 0, bottom: 0, width: 3.5 },
  nokta: { width: 12, height: 12, borderRadius: 6 },
  metin: { flexShrink: 1 },
  isim: { fontSize: 13, fontWeight: "700" },
  isimKucuk: { fontSize: 12 },
  alt: { color: TEMA.renk.yaziEnSoluk, fontSize: 10, fontWeight: "600", marginTop: 1 },
});
