/**
 * NE:       V3 gerçek kart ürünü kataloğunun referans/kanıt denetçisi ve güvenli seçim yardımcıları.
 * NEDEN:    Sadece ürün adına bakarak issuer/program/ağ/grup üyeliği tahmin edilirse Visa/TROY
 *           veya banka ürünü ayrımı bozulur ve yanlış kart kampanyası garanti görünebilir.
 * NASIL:    Kartın doğal programı ile kabul edildiği kampanya ailesini ayrı doğrular; kimlik
 *           tekilliği, çapraz referans, ödeme ağı, grup kapsamı ve beş kanıt başlığını sınar.
 * YAN ETKİ: IO, ağ ve dosya yazımı yapmaz; yalnız denetim ve filtreleme sonucu üretir.
 */
import type { EslemeKaydi, V3EslemeKatalogu } from "./v3Gecis";
import type { TaslakKampanya } from "../tipler";

export type KartKatalogSorunKodu =
  | "duplicate_id"
  | "ambiguous_alias"
  | "issuer_unresolved"
  | "program_unresolved"
  | "campaign_program_unresolved"
  | "group_unresolved"
  | "group_program_mismatch"
  | "payment_network_missing"
  | "evidence_missing"
  | "evidence_invalid"
  | "evidence_unofficial"
  | "group_uncovered";

export interface KartKatalogSorunu {
  code: KartKatalogSorunKodu;
  path: string;
  message: string;
}

export interface KartKatalogDenetimi {
  issues: KartKatalogSorunu[];
  coveredGroupIds: string[];
  uncoveredGroupIds: string[];
  verifiedProductIds: string[];
}

const GEREKLI_KANITLAR = ["identity", "issuer", "program", "network", "group_membership"] as const;
const ODEME_AGLARI = new Set(["visa", "mastercard", "troy", "amex", "other"]);

function normalize(deger: string): string {
  return deger.trim().toLocaleLowerCase("tr-TR").normalize("NFC");
}

function sorun(
  issues: KartKatalogSorunu[],
  code: KartKatalogSorunKodu,
  path: string,
  message: string
): void {
  issues.push({ code, path, message });
}

function idTekilligi(issues: KartKatalogSorunu[], bolumler: EslemeKaydi[][]): void {
  const gorulen = new Map<string, string>();
  for (const bolum of bolumler) {
    for (const kayit of bolum) {
      const onceki = gorulen.get(kayit.id);
      if (onceki) sorun(issues, "duplicate_id", kayit.id, `Kimlik daha önce kullanıldı: ${onceki}`);
      else gorulen.set(kayit.id, kayit.name);
    }
  }
}

function urunAliasTekilligi(issues: KartKatalogSorunu[], urunler: EslemeKaydi[]): void {
  const adlar = new Map<string, string>();
  for (const urun of urunler) {
    for (const aday of [urun.name, ...urun.aliases]) {
      const anahtar = normalize(aday);
      const onceki = adlar.get(anahtar);
      if (onceki && onceki !== urun.id) {
        sorun(issues, "ambiguous_alias", urun.id, `'${aday}' birden fazla ürüne bağlanıyor: ${onceki}`);
      } else {
        adlar.set(anahtar, urun.id);
      }
    }
  }
}

export function kartKatalogunuDogrula(katalog: V3EslemeKatalogu): KartKatalogDenetimi {
  const issues: KartKatalogSorunu[] = [];
  idTekilligi(issues, [
    katalog.programs,
    katalog.issuers,
    katalog.categories,
    katalog.merchants,
    katalog.cardProductGroups,
    katalog.cardProducts,
  ]);
  urunAliasTekilligi(issues, katalog.cardProducts);

  const issuers = new Map(katalog.issuers.map((kayit) => [kayit.id, kayit]));
  const programIds = new Set(katalog.programs.map((kayit) => kayit.id));
  const groups = new Map(katalog.cardProductGroups.map((kayit) => [kayit.id, kayit]));
  const covered = new Set<string>();
  const verifiedProductIds: string[] = [];

  for (const urun of katalog.cardProducts) {
    const yol = `cardProducts.${urun.id}`;
    const urunSorunBaslangici = issues.length;
    const issuer = issuers.get(urun.issuerId);
    if (!issuer) {
      sorun(issues, "issuer_unresolved", `${yol}.issuerId`, `Issuer bulunamadı: ${urun.issuerId}`);
    }
    if (!programIds.has(urun.programId)) {
      sorun(issues, "program_unresolved", `${yol}.programId`, `Program bulunamadı: ${urun.programId}`);
    }
    if (
      urun.eligibleCampaignProgramIds.length === 0 ||
      urun.eligibleCampaignProgramIds.some((programId) => !programIds.has(programId))
    ) {
      sorun(
        issues,
        "campaign_program_unresolved",
        `${yol}.eligibleCampaignProgramIds`,
        "Kartın kabul edildiği kampanya programları açık ve geçerli olmalı."
      );
    }
    if (
      urun.paymentNetworks.length === 0 ||
      urun.paymentNetworks.some((ag) => !ODEME_AGLARI.has(ag))
    ) {
      sorun(issues, "payment_network_missing", `${yol}.paymentNetworks`, "Ödeme ağı açıkça kanıtlanmalı.");
    }
    for (const groupId of urun.eligibilityGroupIds) {
      const grup = groups.get(groupId);
      if (!grup) {
        sorun(issues, "group_unresolved", `${yol}.eligibilityGroupIds`, `Kapsam grubu bulunamadı: ${groupId}`);
      } else if (!urun.eligibleCampaignProgramIds.includes(grup.programId)) {
        sorun(
          issues,
          "group_program_mismatch",
          `${yol}.eligibilityGroupIds`,
          `${groupId}, kartın kabul edildiği kampanya programları arasında değil.`
        );
      }
    }

    if (urun.evidence.length === 0) {
      sorun(issues, "evidence_missing", `${yol}.evidence`, "Resmî ürün kanıtı eksik.");
      continue;
    }
    const desteklenen = new Set(urun.evidence.flatMap((kanit) => kanit.supports));
    let resmiOlmayanKanitVar = false;
    const kanitBozuk = urun.evidence.some((kanit) => {
      try {
        const url = new URL(kanit.officialUrl);
        if (
          issuer &&
          !issuer.officialDomains.some(
            (domain) => url.hostname === domain || url.hostname.endsWith(`.${domain}`)
          )
        ) {
          resmiOlmayanKanitVar = true;
        }
        return (
          url.protocol !== "https:" ||
          kanit.note.trim().length < 10 ||
          Number.isNaN(Date.parse(kanit.verifiedAt))
        );
      } catch {
        return true;
      }
    });
    if (kanitBozuk) {
      sorun(issues, "evidence_invalid", `${yol}.evidence`, "Kanıt URL/not/doğrulama zamanı geçersiz.");
    }
    if (resmiOlmayanKanitVar) {
      sorun(
        issues,
        "evidence_unofficial",
        `${yol}.evidence`,
        "Kanıt bağlantısı kartı veren kurumun izinli resmî alan adında değil."
      );
    }
    const eksikKanitlar = GEREKLI_KANITLAR.filter((alan) => !desteklenen.has(alan));
    if (eksikKanitlar.length > 0) {
      sorun(issues, "evidence_missing", `${yol}.evidence`, `Eksik kanıt başlıkları: ${eksikKanitlar.join(", ")}`);
    }
    const urunDogrulandi = issues.length === urunSorunBaslangici;
    if (urunDogrulandi) {
      verifiedProductIds.push(urun.id);
      if (urun.active) urun.eligibilityGroupIds.forEach((groupId) => covered.add(groupId));
    }
  }

  const uncoveredGroupIds = katalog.cardProductGroups
    .map((grup) => grup.id)
    .filter((id) => !covered.has(id));
  for (const groupId of uncoveredGroupIds) {
    sorun(issues, "group_uncovered", `cardProductGroups.${groupId}`, "Aktif ve kanıtlı gerçek kart ürünü bağlı değil.");
  }

  return {
    issues,
    coveredGroupIds: [...covered].toSorted(),
    uncoveredGroupIds: uncoveredGroupIds.toSorted(),
    verifiedProductIds: verifiedProductIds.toSorted(),
  };
}

export function kartUrunleriniFiltrele(
  katalog: V3EslemeKatalogu,
  arama: string,
  issuerId: string | null
): V3EslemeKatalogu["cardProducts"] {
  const aranan = normalize(arama);
  return katalog.cardProducts
    .filter((urun) => urun.active)
    .filter((urun) => !issuerId || urun.issuerId === issuerId)
    .filter((urun) => {
      if (!aranan) return true;
      const issuer = katalog.issuers.find((aday) => aday.id === urun.issuerId);
      return [urun.name, ...urun.aliases, issuer?.name ?? ""]
        .map(normalize)
        .some((aday) => aday.includes(aranan));
    })
    .toSorted((a, b) => a.name.localeCompare(b.name, "tr"));
}

/**
 * Kart yüzünde gösterilecek PROGRAM ADI (display) — TEK KAYNAK.
 * DİKKAT (bilinçli, sadeleştirilmez): DISPLAY için eligibleCampaignProgramIds[0] (kampanya ailesi)
 * kullanılır; kart RENGİ ise kartGorunumu(urun.programId,…) yani NATURAL programId'den gelir. İkisi
 * FARKLI olabilir (Shop&Fly/Miles&Smiles/Amex → Bonus; Free/Akbank/Wings → Axess). Bu ayrım kaldırılırsa
 * o kartlar sessizce jenerik grafite düşer (logo/renk kaybı).
 */
export function urunProgramAdi(
  katalog: V3EslemeKatalogu,
  urun: V3EslemeKatalogu["cardProducts"][number]
): string {
  const programId = urun.eligibleCampaignProgramIds[0] ?? urun.programId;
  return katalog.programs.find((p) => p.id === programId)?.name ?? urun.name;
}

export function kartUrunuKampanyaProgramAdlari(
  katalog: V3EslemeKatalogu,
  productIds: string[]
): string[] {
  const secili = new Set(productIds);
  const programIds = new Set(
    katalog.cardProducts
      .filter((urun) => secili.has(urun.id) && urun.active)
      .flatMap((urun) => urun.eligibleCampaignProgramIds)
  );
  return katalog.programs
    .filter((program) => programIds.has(program.id))
    .map((program) => program.name)
    .toSorted((a, b) => a.localeCompare(b, "tr"));
}

export function eskiKampanyaKartUrununeUyarMi(
  kampanya: Pick<TaslakKampanya, "program" | "gecerli_kartlar">,
  katalog: V3EslemeKatalogu,
  productId: string
): boolean {
  const urun = katalog.cardProducts.find((aday) => aday.id === productId && aday.active);
  if (!urun || !kampanya.gecerli_kartlar || kampanya.gecerli_kartlar.length === 0) return false;

  const kampanyaProgramIds = katalog.programs
    .filter((program) =>
      [program.name, ...program.aliases].some(
        (aday) => normalize(aday) === normalize(kampanya.program)
      )
    )
    .map((program) => program.id)
    .filter((programId) => urun.eligibleCampaignProgramIds.includes(programId));
  if (kampanyaProgramIds.length === 0) return false;

  const kapsamGrupIds = katalog.cardProductGroups
    .filter((grup) => kampanyaProgramIds.includes(grup.programId))
    .filter((grup) =>
      kampanya.gecerli_kartlar?.some((ifade) =>
        [grup.name, ...grup.aliases].some(
          (aday) => normalize(aday) === normalize(ifade)
        )
      )
    )
    .map((grup) => grup.id);

  return kapsamGrupIds.some((groupId) => urun.eligibilityGroupIds.includes(groupId));
}
