/**
 * NE:       Sekme geçiş sarmalayıcısı — App.tsx'teki dört sekme panelini (karar / fırsatlar /
 *           karnem / cüzdan) saran TEK katman. Giren paneli kısa bir opacity + translateY ile
 *           eritip oturtur; sekme ÇUBUĞU bu sarmalayıcının DIŞINDA sabit kalır (değişmez çapa).
 * NEDEN:    Mevcut sekme değişimi anlık koşullu render'la (sekme===... &&) sert kesme yapıyordu;
 *           göz yeni içeriğin nerede oluşacağını kaybediyordu. Tek görsel-süreklilik hamlesiyle
 *           bakış yeni panelin en üstüne sıfırlanır — "yüzey tazelendi" güveni, ışınlanma değil
 *           yumuşak kayma. Odağı KARARA taşır, dağıtmaz.
 * NASIL:    App bu bileşeni key={sekme} ile sarar → her sekmede yeniden mount → useEffect mount-fire.
 *           hareketAzalt ise animasyon YOK, panel anında son durumda (opacity 1) belirir
 *           (erişilebilirlik: statik dinginlik hali). Değilse gec 0→1: requestAnimationFrame ile
 *           bir kare ertelenip (yeni ScrollView'in ilk layout'uyla aynı karede çakışıp jank
 *           üretmesini önler) SURE.sekme (=TEMA.zaman.sekme) süresinde EASING.cikis (çıkış-cubic)
 *           ile erir. YALNIZ opacity + translateY sürülür → useNativeDriver:true (JS thread'e yük yok, 60fps).
 *           Süre/easing sabitleri ../hareket'ten okunur (tek kaynak: OdakHale/okuma-merdiveniyle aynı dil).
 * YAN ETKİ: Sarmalayıcı flex:1 alır → içteki ScrollView'in scroll yüksekliğini korur. Dokunmayı
 *           YUTMAZ (arka plan katmanı değil; pointerEvents serbest bırakılır — panel etkileşimli
 *           kalır). Layout-anim (width/height/top) YOK. Para/karar mantığına, BuyukCevap'ın kendi
 *           giriş+gleam animasyonuna DOKUNMAZ — yalnız dıştaki panel yüzeyini eritir.
 */
import { useEffect, useRef } from "react";
import type { ReactNode } from "react";
import { Animated } from "react-native";
import { SURE, EASING } from "../hareket";

export function SekmeGecis({
  sekme,
  hareketAzalt = false,
  children,
}: {
  /** Aktif sekme anahtarı — App.tsx bunu hem prop hem key={sekme} olarak geçer (değişince yeni mount → giriş tetiklenir) */
  sekme: string;
  /** Erişilebilirlik: hareket azaltma açıkken animasyon çalışmaz; panel anında son durumda belirir */
  hareketAzalt?: boolean;
  /** Aktif sekmenin ScrollView paneli (giren içerik) */
  children: ReactNode;
}) {
  // Tek animasyon değeri: 0 = gizli + 8px aşağıda, 1 = tam görünür + oturmuş.
  // hareketAzalt'ta baştan 1 (ilk kareden dingin son durum, hiç titremez).
  const gec = useRef(new Animated.Value(hareketAzalt ? 1 : 0)).current;

  useEffect(() => {
    // Erişilebilirlik önce gelir: hareket azaltılıyorsa animasyon yok, dingin son durum.
    if (hareketAzalt) {
      gec.setValue(1);
      return;
    }
    // Temiz 0'dan başlat: key'li kullanımda zaten 0; key'siz entegrasyonda (prop değişince
    // remount olmadan) bu satır giriş animasyonunu güvenle yeniden tetikler.
    gec.setValue(0);
    let animasyon: Animated.CompositeAnimation | null = null;
    // rAF ile bir kare ertele: fade + settle, yeni ScrollView'in ilk layout'uyla aynı karede
    // çakışıp kare düşürmesini önler → giriş yağ gibi akar.
    const id = requestAnimationFrame(() => {
      animasyon = Animated.timing(gec, {
        toValue: 1,
        duration: SURE.sekme,
        easing: EASING.cikis,
        useNativeDriver: true,
      });
      animasyon.start();
    });
    // Unmount / yeniden çalışma temizliği: bekleyen kareyi iptal et, çalışan animasyonu durdur
    // (bayat animasyonun bir sonraki panele sızmasını / kayıp güncellemeyi önler).
    return () => {
      cancelAnimationFrame(id);
      animasyon?.stop();
    };
  }, [gec, sekme, hareketAzalt]);

  return (
    <Animated.View
      style={{
        flex: 1,
        opacity: gec,
        transform: [
          { translateY: gec.interpolate({ inputRange: [0, 1], outputRange: [8, 0] }) },
        ],
      }}
    >
      {children}
    </Animated.View>
  );
}
