/**
 * NE:       KartAkıl v3 deterministik kampanya uygunluk ve kart sıralama motoru.
 * NEDEN:    Eski motor yalnız kategoriye bakıyor; markete özel yüksek kazançlı yanlış kampanya
 *           başka markette veya tüm adaylar uygunsuzken ilgisiz kaynak kart sonucunda görünebiliyor.
 * NASIL:    Merchant, güven, kanal, POS, gerçek kart ürünü, katılım, ilerleme, fayda tavanı, Türkiye
 *           günü, kaynak tazeliği ve insan onayını saf fonksiyonlarla sınar; bilinmeyen tavanı kesin
 *           saymaz, sıfır faydayı kazanç diye sunmaz, OR alternatiflerinde yalnız en ulaşılabilir
 *           başarısız yolu açıklar ve taksit ayını sayısal olarak sıralar.
 * YAN ETKİ: IO ve ağ çağrısı yoktur; mevcut karar.ts akışı değiştirilmez; stale veya tavanı bilinmeyen
 *           uygun aday unknown olur, hard-ineligible adayın hükmü değişmez.
 */
import type {
  CampaignProgress,
  CampaignRule,
  CampaignV3,
  CardProduct,
  DecisionInputV3,
  DecisionResultV3,
  KaynakTazeligi,
  MarketContext,
  UygunlukDurumu,
  UserWalletItem,
} from "../../../shared/src/index";
import { turkiyeTakvimTarihi } from "./tarih";

type KuralHukmu = "pass" | "fail" | "unknown";

interface KuralBulgu {
  hukum: KuralHukmu;
  kod: string;
  aciklama: string;
  kullaniciTamamlayabilir: boolean;
}

interface KuralSonucu {
  hukum: KuralHukmu;
  bulgular: KuralBulgu[];
}

interface KuralBaglami {
  girdi: DecisionInputV3;
  kartUrunu: CardProduct;
  cuzdanKarti: UserWalletItem;
  ilerleme: CampaignProgress | null;
}

export interface CampaignEvaluation {
  campaignId: string;
  state: UygunlukDurumu;
  guaranteedBenefitTL: number;
  potentialBenefitTL: number;
  nonCashBenefit: string | null;
  installmentMonths: number | null;
  blockingReasons: string[];
  criticalConditions: string[];
  calculationSteps: string[];
  sourceUrl: string;
  freshness: KaynakTazeligi;
  humanApproved: boolean;
}

const GUN_MS = 86_400_000;

function sonuc(hukum: KuralHukmu, bulgular: KuralBulgu[] = []): KuralSonucu {
  return { hukum, bulgular };
}

function bulgu(
  hukum: KuralHukmu,
  kod: string,
  aciklama: string,
  kullaniciTamamlayabilir = false
): KuralSonucu {
  return sonuc(hukum, [{ hukum, kod, aciklama, kullaniciTamamlayabilir }]);
}

/**
 * NE:       Geçemeyen OR dalları arasından kullanıcıya en ulaşılabilir tek alternatifi seçer.
 * NEDEN:    Birbirinin alternatifi olan dalların sert engellerini birleştirmek, düzeltilebilir bir yolu
 *           yanlışlıkla "uygun değil" durumuna çevirebilir ve kullanıcıya çelişkili nedenler gösterebilir.
 * NASIL:    Önce sert engeli olmayanı; sonra daha az bilinmeyen, düzeltilebilir hata ve toplam bulgu
 *           taşıyanı seçer. Tam eşitlikte kaynak sırasını koruyarak deterministik kalır.
 * YAN ETKİ: Yok; sonuçları değiştirmez, yalnız seçilecek dalı döndürür.
 */
function enUlasilabilirAlternatif(sonuclar: KuralSonucu[]): KuralSonucu {
  const ilkSonuc = sonuclar[0];
  if (!ilkSonuc) {
    return bulgu("fail", "empty_alternative", "Kampanya alternatif kuralı güvenli biçimde tanımlanmamış.");
  }
  const puan = (aday: KuralSonucu): readonly number[] => [
    aday.bulgular.filter(
      (madde) => madde.hukum === "fail" && !madde.kullaniciTamamlayabilir
    ).length,
    aday.bulgular.filter((madde) => madde.hukum === "unknown").length,
    aday.bulgular.filter(
      (madde) => madde.hukum === "fail" && madde.kullaniciTamamlayabilir
    ).length,
    aday.bulgular.length,
  ];
  const onceMi = (aday: KuralSonucu, mevcut: KuralSonucu): boolean => {
    const adayPuani = puan(aday);
    const mevcutPuani = puan(mevcut);
    return adayPuani.some(
      (deger, sira) =>
        deger !== mevcutPuani[sira] &&
        adayPuani.slice(0, sira).every((onceki, oncekiSira) => onceki === mevcutPuani[oncekiSira]) &&
        deger < mevcutPuani[sira]
    );
  };
  return sonuclar.slice(1).reduce(
    (mevcut, aday) => (onceMi(aday, mevcut) ? aday : mevcut),
    ilkSonuc
  );
}

function marketKesinMi(market: MarketContext): boolean {
  if (!market.selected) return false;
  if (market.status === "user_confirmed" || market.status === "manual") return true;
  return (
    market.status === "detected" &&
    market.confidenceBand === "high" &&
    market.selected.confidence >= 0.85
  );
}

function tarihGunu(iso: string): string {
  return turkiyeTakvimTarihi(new Date(iso));
}

function tarihMs(iso: string): number {
  const [yil, ay, gun] = tarihGunu(iso).split("-").map(Number);
  return Date.UTC(yil, ay - 1, gun);
}

export function kaynakTazeligi(kampanya: CampaignV3, degerlendirmeAni: string): KaynakTazeligi {
  const gecenGun = Math.max(
    0,
    Math.floor((tarihMs(degerlendirmeAni) - tarihMs(kampanya.source.verifiedAt)) / GUN_MS)
  );
  if (gecenGun <= kampanya.source.maxAgeDays) return "fresh";
  if (gecenGun <= kampanya.source.maxAgeDays * 2) return "aging";
  return "stale";
}

function kuralDegerlendir(kural: CampaignRule, baglam: KuralBaglami): KuralSonucu {
  switch (kural.op) {
    case "all": {
      const sonuclar = kural.rules.map((alt) => kuralDegerlendir(alt, baglam));
      const bulgular = sonuclar.flatMap((alt) => alt.bulgular);
      if (sonuclar.some((alt) => alt.hukum === "fail")) return sonuc("fail", bulgular);
      if (sonuclar.some((alt) => alt.hukum === "unknown")) return sonuc("unknown", bulgular);
      return sonuc("pass", bulgular);
    }

    case "any": {
      const sonuclar = kural.rules.map((alt) => kuralDegerlendir(alt, baglam));
      const gecen = sonuclar.find((alt) => alt.hukum === "pass");
      if (gecen) return gecen;
      const bilinmeyenler = sonuclar.filter((alt) => alt.hukum === "unknown");
      if (bilinmeyenler.length > 0) {
        return enUlasilabilirAlternatif(bilinmeyenler);
      }
      return enUlasilabilirAlternatif(sonuclar);
    }

    case "not": {
      const alt = kuralDegerlendir(kural.rule, baglam);
      if (alt.hukum === "unknown") return alt;
      const tersHukum = alt.hukum === "pass" ? "fail" : "pass";
      return sonuc(
        tersHukum,
        alt.bulgular.map((madde) => ({
          ...madde,
          hukum: madde.hukum === "pass" ? "fail" : madde.hukum === "fail" ? "pass" : "unknown",
          kod: `not_${madde.kod}`,
          aciklama:
            tersHukum === "fail"
              ? `Hariç tutma koşulu oluştu: ${madde.aciklama}`
              : `Hariç tutma koşulu oluşmadı: ${madde.aciklama}`,
          kullaniciTamamlayabilir: false,
        }))
      );
    }

    case "merchant_in": {
      const market = baglam.girdi.market;
      if (!market.selected || !marketKesinMi(market)) {
        return bulgu("unknown", "merchant_unknown", "Market teyidi gerekiyor.");
      }
      return kural.merchantIds.includes(market.selected.merchantId)
        ? bulgu("pass", "merchant_match", `${market.selected.merchantName} kampanya kapsamında.`)
        : bulgu("fail", "merchant_mismatch", "Bu kampanya seçili markette geçerli değil.");
    }

    case "category_in": {
      const market = baglam.girdi.market;
      if (!market.selected || !marketKesinMi(market)) {
        return bulgu("unknown", "category_unknown", "Market kategorisi teyit edilemedi.");
      }
      return market.selected.categoryIds.some((kategori) => kural.categoryIds.includes(kategori))
        ? bulgu("pass", "category_match", "Market kategorisi kampanya kapsamında.")
        : bulgu("fail", "category_mismatch", "Market kategorisi kampanya kapsamında değil.");
    }

    case "channel_in":
      if (baglam.girdi.channel === "unknown") {
        return bulgu("unknown", "channel_unknown", "Ödeme kanalı teyit edilmeli.");
      }
      return kural.channels.includes(baglam.girdi.channel)
        ? bulgu("pass", "channel_match", "Ödeme kanalı uygun.")
        : bulgu("fail", "channel_mismatch", "Kampanya bu ödeme kanalında geçerli değil.");

    case "pos_in":
      if (!baglam.girdi.posId) {
        return bulgu("unknown", "pos_unknown", "Kullanılacak POS teyit edilmeli.");
      }
      return kural.posIds.includes(baglam.girdi.posId)
        ? bulgu("pass", "pos_match", "POS koşulu sağlanıyor.")
        : bulgu("fail", "pos_mismatch", "Kampanya bu POS üzerinden geçerli değil.");

    case "card_product_in":
      return kural.cardProductIds.includes(baglam.kartUrunu.id)
        ? bulgu("pass", "card_product_match", `${baglam.kartUrunu.productName} kampanyaya uygun.`)
        : bulgu("fail", "card_product_mismatch", "Gerçek kart ürünü kampanyaya uygun değil.");

    case "card_product_group_in":
      return baglam.kartUrunu.eligibilityGroupIds.some((grup) => kural.groupIds.includes(grup))
        ? bulgu("pass", "card_product_group_match", `${baglam.kartUrunu.productName} kart kapsamına uygun.`)
        : bulgu("fail", "card_product_group_mismatch", "Gerçek kart ürünü kampanya kart kapsamına uygun değil.");

    case "user_segment_in": {
      const uyuyor = baglam.cuzdanKarti.userSegmentTags.some((etiket) =>
        kural.segmentTags.includes(etiket)
      );
      if (uyuyor) return bulgu("pass", "segment_match", "Kullanıcı segmenti uygun.");
      if (baglam.cuzdanKarti.userSegmentTags.length === 0) {
        return bulgu("unknown", "segment_unknown", "Kart segmenti teyit edilmeli.");
      }
      return bulgu("fail", "segment_mismatch", "Kart segmenti kampanyaya uygun değil.");
    }

    case "min_single_transaction":
      return baglam.girdi.basketAmountTL >= kural.amountTL
        ? bulgu("pass", "single_spend_match", "Sepet işlem eşiğini karşılıyor.")
        : bulgu(
            "fail",
            "single_spend_short",
            `Sepeti ${paraYaz(kural.amountTL)} TL'ye tamamlamak gerekiyor.`,
            true
          );

    case "min_cumulative_spend": {
      const onceki = baglam.ilerleme?.cumulativeSpendTL;
      if (onceki == null) {
        return bulgu("unknown", "cumulative_unknown", "Kümülatif harcama ilerlemesi bilinmiyor.");
      }
      return onceki + baglam.girdi.basketAmountTL >= kural.amountTL
        ? bulgu("pass", "cumulative_match", "Kümülatif harcama eşiği karşılanıyor.")
        : bulgu(
            "fail",
            "cumulative_short",
            `Kümülatif eşiğe ${paraYaz(kural.amountTL - onceki - baglam.girdi.basketAmountTL)} TL kaldı.`,
            true
          );
    }

    case "transaction_count": {
      const onceki = baglam.ilerleme?.transactionCount;
      if (onceki == null) {
        return bulgu("unknown", "transaction_count_unknown", "İşlem adedi ilerlemesi bilinmiyor.");
      }
      const yeniAdet = onceki + 1;
      if (kural.max != null && yeniAdet > kural.max) {
        return bulgu("fail", "transaction_count_exceeded", "Kampanyanın işlem adedi hakkı dolmuş.");
      }
      return yeniAdet >= kural.min
        ? bulgu("pass", "transaction_count_match", `${yeniAdet}. işlem koşulu karşılanıyor.`)
        : bulgu(
            "fail",
            "transaction_count_short",
            `${kural.min - yeniAdet} işlem daha gerekiyor.`,
            true
          );
    }

    case "distinct_days": {
      const gun = baglam.ilerleme?.distinctDays;
      const bugunSayildi = baglam.ilerleme?.currentDayAlreadyCounted;
      if (gun == null || bugunSayildi == null) {
        return bulgu("unknown", "distinct_days_unknown", "Farklı gün ilerlemesi bilinmiyor.");
      }
      const yeniGun = gun + (bugunSayildi ? 0 : 1);
      return yeniGun >= kural.min
        ? bulgu("pass", "distinct_days_match", `${yeniGun} farklı gün koşulu karşılanıyor.`)
        : bulgu(
            "fail",
            "distinct_days_short",
            `${kural.min - yeniGun} farklı gün daha gerekiyor.`,
            true
          );
    }

    case "enrollment_required": {
      const katilim = baglam.ilerleme?.enrollment ?? "unknown";
      if (katilim === "joined") return bulgu("pass", "enrollment_match", "Kampanyaya katılım tamam.");
      if (katilim === "not_joined") {
        return bulgu(
          "fail",
          "enrollment_missing",
          `${kural.method} ile kampanyaya katılmak gerekiyor.`,
          true
        );
      }
      return bulgu("unknown", "enrollment_unknown", "Kampanyaya katılım durumu bilinmiyor.");
    }

    case "date_between": {
      const bugun = tarihGunu(baglam.girdi.evaluatedAt);
      return bugun >= kural.start && bugun <= kural.end
        ? bulgu("pass", "date_match", "Kampanya bugün geçerli.")
        : bulgu("fail", "date_mismatch", "Kampanya bugün geçerli değil.");
    }
  }
}

function paraYaz(tutar: number): string {
  return Math.max(0, tutar).toLocaleString("tr-TR", { maximumFractionDigits: 0 });
}

function faydaHesapla(
  kampanya: CampaignV3,
  baglam: KuralBaglami
): {
  kesinTL: number;
  belirsizEkTL: number;
  nakitDisi: string | null;
  taksitAyi: number | null;
  hesap: string[];
} {
  const sepetTL = baglam.girdi.basketAmountTL;
  const kazanilan = baglam.ilerleme?.earnedBenefitTL ?? 0;
  switch (kampanya.benefit.type) {
    case "fixed_tl": {
      const kalanTavan =
        kampanya.benefit.capTL == null
          ? kampanya.benefit.amountTL
          : Math.max(0, kampanya.benefit.capTL - kazanilan);
      const tl = Math.min(kampanya.benefit.amountTL, kalanTavan);
      return { kesinTL: tl, belirsizEkTL: 0, nakitDisi: null, taksitAyi: null, hesap: [`Sabit fayda: ${paraYaz(tl)} TL`] };
    }
    case "percent_tl": {
      const ham = Math.round((sepetTL * kampanya.benefit.rate) / 100);
      const kalanTavan =
        kampanya.benefit.capTL == null ? ham : Math.max(0, kampanya.benefit.capTL - kazanilan);
      const tl = Math.min(ham, kalanTavan);
      return {
        kesinTL: tl,
        belirsizEkTL: 0,
        nakitDisi: null,
        taksitAyi: null,
        hesap: [`%${kampanya.benefit.rate} × ${paraYaz(sepetTL)} TL = ${paraYaz(tl)} TL`],
      };
    }
    case "tiered_fixed_tl": {
      const sirali = [...kampanya.benefit.tiers].sort((a, b) => a.minSpendTL - b.minSpendTL);
      const uyan = sirali.filter((kademe) => sepetTL >= kademe.minSpendTL).at(-1);
      const ham = uyan?.benefitTL ?? 0;
      const kalanTavan =
        kampanya.benefit.capTL == null ? ham : Math.max(0, kampanya.benefit.capTL - kazanilan);
      const tl = Math.min(ham, kalanTavan);
      const ilkKademe = sirali[0];
      const ilkKademePotansiyeli = !uyan
        ? Math.min(
            ilkKademe.benefitTL,
            kampanya.benefit.capTL == null
              ? ilkKademe.benefitTL
              : Math.max(0, kampanya.benefit.capTL - kazanilan)
          )
        : 0;
      return {
        kesinTL: tl,
        belirsizEkTL: ilkKademePotansiyeli,
        nakitDisi: null,
        taksitAyi: null,
        hesap: uyan
          ? [
              `${paraYaz(sepetTL)} TL sepet, ${paraYaz(uyan.minSpendTL)} TL kademesi → ${paraYaz(tl)} TL`,
            ]
          : [
              `İlk ${paraYaz(ilkKademe.benefitTL)} TL fayda için ${paraYaz(
                Math.max(0, ilkKademe.minSpendTL - sepetTL)
              )} TL daha harcama gerekir.`,
            ],
      };
    }
    case "conditional_fixed_tl": {
      const kalanTavan =
        kampanya.benefit.capTL == null
          ? Number.POSITIVE_INFINITY
          : Math.max(0, kampanya.benefit.capTL - kazanilan);
      let kesinHam = kampanya.benefit.baseAmountTL;
      let belirsizHam = 0;
      const hesap = [`Temel fayda: ${paraYaz(kampanya.benefit.baseAmountTL)} TL`];
      for (const bonus of kampanya.benefit.bonuses) {
        const hukum = kuralDegerlendir(bonus.when, baglam).hukum;
        if (hukum === "pass") {
          kesinHam += bonus.amountTL;
          hesap.push(`${bonus.label}: +${paraYaz(bonus.amountTL)} TL`);
        } else if (hukum === "unknown") {
          belirsizHam += bonus.amountTL;
          hesap.push(`${bonus.label}: teyit edilirse +${paraYaz(bonus.amountTL)} TL`);
        }
      }
      const kesinTL = Math.min(kesinHam, kalanTavan);
      const belirsizEkTL = Math.max(0, Math.min(kesinHam + belirsizHam, kalanTavan) - kesinTL);
      return { kesinTL, belirsizEkTL, nakitDisi: null, taksitAyi: null, hesap };
    }
    case "installment":
      return {
        kesinTL: 0,
        belirsizEkTL: 0,
        nakitDisi: `${kampanya.benefit.months} taksit`,
        taksitAyi: kampanya.benefit.months,
        hesap: [`${kampanya.benefit.months} taksit; doğrudan TL kazancı değildir.`],
      };
  }
}

function kampanyaTarihAraligindaMi(kampanya: CampaignV3, an: string): boolean {
  const gun = tarihGunu(an);
  return gun >= kampanya.startsAt && gun <= kampanya.endsAt;
}

function kartKapsamiGarantiliMi(kural: CampaignRule): boolean {
  if (kural.op === "card_product_in" || kural.op === "card_product_group_in") return true;
  if (kural.op === "all") return kural.rules.some(kartKapsamiGarantiliMi);
  if (kural.op === "any") {
    return kural.rules.length > 0 && kural.rules.every(kartKapsamiGarantiliMi);
  }
  return false;
}

function durumBelirle(kural: KuralSonucu): UygunlukDurumu {
  if (kural.hukum === "pass") return "guaranteed";
  const hatalar = kural.bulgular.filter((madde) => madde.hukum === "fail");
  if (hatalar.some((madde) => !madde.kullaniciTamamlayabilir)) return "ineligible";
  if (kural.bulgular.some((madde) => madde.hukum === "unknown")) return "unknown";
  if (kural.hukum === "unknown") return "unknown";
  return hatalar.length > 0 && hatalar.every((madde) => madde.kullaniciTamamlayabilir)
    ? "potential"
    : "ineligible";
}

export function kampanyaDegerlendir(
  kampanya: CampaignV3,
  kartUrunu: CardProduct,
  cuzdanKarti: UserWalletItem,
  girdi: DecisionInputV3
): CampaignEvaluation {
  const ilerleme =
    girdi.campaignProgress.find((aday) => aday.campaignId === kampanya.id) ?? null;
  const tazelik = kaynakTazeligi(kampanya, girdi.evaluatedAt);
  const kuralBaglami = { girdi, kartUrunu, cuzdanKarti, ilerleme };
  const fayda = faydaHesapla(kampanya, kuralBaglami);

  if (!kampanya.humanApproved) {
    return {
      campaignId: kampanya.id,
      state: "ineligible",
      guaranteedBenefitTL: 0,
      potentialBenefitTL: 0,
      nonCashBenefit: fayda.nakitDisi,
      installmentMonths: fayda.taksitAyi,
      blockingReasons: ["Kampanya insan onayından geçmemiş."],
      criticalConditions: [],
      calculationSteps: fayda.hesap,
      sourceUrl: kampanya.source.officialUrl,
      freshness: tazelik,
      humanApproved: false,
    };
  }

  if (!kartKapsamiGarantiliMi(kampanya.rule)) {
    return {
      campaignId: kampanya.id,
      state: "ineligible",
      guaranteedBenefitTL: 0,
      potentialBenefitTL: 0,
      nonCashBenefit: fayda.nakitDisi,
      installmentMonths: fayda.taksitAyi,
      blockingReasons: ["Kampanyanın kanıtlı gerçek kart kapsamı tanımlı değil."],
      criticalConditions: [],
      calculationSteps: fayda.hesap,
      sourceUrl: kampanya.source.officialUrl,
      freshness: tazelik,
      humanApproved: true,
    };
  }

  if (!kampanyaTarihAraligindaMi(kampanya, girdi.evaluatedAt)) {
    return {
      campaignId: kampanya.id,
      state: "ineligible",
      guaranteedBenefitTL: 0,
      potentialBenefitTL: 0,
      nonCashBenefit: fayda.nakitDisi,
      installmentMonths: fayda.taksitAyi,
      blockingReasons: ["Kampanya bugün geçerli değil."],
      criticalConditions: [],
      calculationSteps: fayda.hesap,
      sourceUrl: kampanya.source.officialUrl,
      freshness: tazelik,
      humanApproved: true,
    };
  }

  const kural = kuralDegerlendir(kampanya.rule, kuralBaglami);
  let state = durumBelirle(kural);
  const engeller = kural.bulgular
    .filter((madde) => madde.hukum !== "pass")
    .map((madde) => madde.aciklama);
  const kosullar = kural.bulgular
    .filter((madde) => madde.hukum === "pass")
    .map((madde) => madde.aciklama);

  const faydaTavani = kampanya.benefit.type === "installment" ? null : kampanya.benefit.capTL;
  if (state !== "ineligible" && faydaTavani !== null && ilerleme?.earnedBenefitTL == null) {
    state = "unknown";
    engeller.push("Kampanya fayda tavanında daha önce kullanılan tutar bilinmiyor.");
  }

  if (
    state !== "ineligible" &&
    kampanya.benefit.type === "tiered_fixed_tl" &&
    !kampanya.benefit.tiers.some((kademe) => girdi.basketAmountTL >= kademe.minSpendTL)
  ) {
    if (state === "guaranteed") state = "potential";
    const ilkKademe = [...kampanya.benefit.tiers].sort((a, b) => a.minSpendTL - b.minSpendTL)[0];
    engeller.push(
      `İlk fayda kademesi için ${paraYaz(
        Math.max(0, ilkKademe.minSpendTL - girdi.basketAmountTL)
      )} TL daha gerekir.`
    );
  }

  if (
    state !== "ineligible" &&
    fayda.nakitDisi === null &&
    fayda.kesinTL + fayda.belirsizEkTL <= 0
  ) {
    if (
      faydaTavani !== null &&
      ilerleme?.earnedBenefitTL != null &&
      ilerleme.earnedBenefitTL >= faydaTavani
    ) {
      state = "ineligible";
      engeller.push("Kampanya fayda tavanı daha önce tamamen kullanılmış.");
    } else {
      state = "ineligible";
      engeller.push("Bu sepet tutarında doğrulanmış bir nakit fayda oluşmuyor.");
    }
  }

  if (tazelik !== "fresh" && state !== "ineligible") {
    state = "unknown";
    engeller.push(
      tazelik === "aging"
        ? "Kampanya kaynağı güncellik sınırını aştı; yeniden doğrulanmalı."
        : "Kampanya kaynağı yeniden doğrulanmalı."
    );
  }

  return {
    campaignId: kampanya.id,
    state,
    guaranteedBenefitTL: state === "guaranteed" ? fayda.kesinTL : 0,
    potentialBenefitTL:
      state === "guaranteed"
        ? fayda.belirsizEkTL
        : state === "potential" || state === "unknown"
          ? fayda.kesinTL + fayda.belirsizEkTL
          : 0,
    nonCashBenefit: fayda.nakitDisi,
    installmentMonths: fayda.taksitAyi,
    blockingReasons: engeller,
    criticalConditions: kosullar,
    calculationSteps: fayda.hesap,
    sourceUrl: kampanya.source.officialUrl,
    freshness: tazelik,
    humanApproved: true,
  };
}

const DURUM_ONCELIGI: Record<UygunlukDurumu, number> = {
  guaranteed: 0,
  potential: 1,
  unknown: 2,
  ineligible: 3,
};

function degerlendirmeSirala(a: CampaignEvaluation, b: CampaignEvaluation): number {
  if (DURUM_ONCELIGI[a.state] !== DURUM_ONCELIGI[b.state]) {
    return DURUM_ONCELIGI[a.state] - DURUM_ONCELIGI[b.state];
  }
  if (b.guaranteedBenefitTL !== a.guaranteedBenefitTL) {
    return b.guaranteedBenefitTL - a.guaranteedBenefitTL;
  }
  if (b.potentialBenefitTL !== a.potentialBenefitTL) {
    return b.potentialBenefitTL - a.potentialBenefitTL;
  }
  if ((b.installmentMonths ?? 0) !== (a.installmentMonths ?? 0)) {
    return (b.installmentMonths ?? 0) - (a.installmentMonths ?? 0);
  }
  return a.campaignId.localeCompare(b.campaignId, "tr");
}

function bosKarar(
  cuzdanKarti: UserWalletItem,
  kartUrunu: CardProduct | null,
  neden: string
): DecisionResultV3 {
  return {
    walletItemId: cuzdanKarti.id,
    cardProductId: kartUrunu?.id ?? cuzdanKarti.cardProductId,
    campaignId: null,
    state: kartUrunu ? "ineligible" : "unknown",
    guaranteedBenefitTL: 0,
    potentialBenefitTL: 0,
    nonCashBenefit: null,
    installmentMonths: null,
    blockingReasons: [neden],
    criticalConditions: [],
    calculationSteps: [],
    sourceUrls: [],
    freshness: null,
    humanApproved: false,
  };
}

/**
 * NE:       Her gerçek cüzdan kartını en iyi onaylı ve uygulanabilir kampanyasıyla temsil eder.
 * NEDEN:    Tüm adaylar ineligible ise alfabetik ilk kampanyayı seçmek ilgisiz kaynak ve neden gösterir.
 * NASIL:    Sıralanan adayların tamamı uygunsuzsa campaignId/source taşımayan bosKarar döndürür.
 * YAN ETKİ: Uygun, potansiyel veya bilinmeyen adayların mevcut sıralama davranışı değişmez.
 */
export function kartlariSirala(kampanyalar: CampaignV3[], girdi: DecisionInputV3): DecisionResultV3[] {
  const sonuclar = girdi.wallet.map((cuzdanKarti) => {
    const kartUrunu =
      girdi.cardProducts.find((aday) => aday.id === cuzdanKarti.cardProductId && aday.active) ?? null;
    if (!kartUrunu) return bosKarar(cuzdanKarti, null, "Gerçek kart ürünü bulunamadı veya pasif.");

    const adaylar = kampanyalar
      .filter((kampanya) => kampanya.humanApproved)
      .map((kampanya) => kampanyaDegerlendir(kampanya, kartUrunu, cuzdanKarti, girdi))
      .sort(degerlendirmeSirala);

    const enIyi = adaylar[0];
    if (!enIyi) return bosKarar(cuzdanKarti, kartUrunu, "Bu kart için onaylı kampanya yok.");
    if (adaylar.every((aday) => aday.state === "ineligible")) {
      return bosKarar(cuzdanKarti, kartUrunu, "Bu kart için uygulanabilir onaylı kampanya yok.");
    }

    return {
      walletItemId: cuzdanKarti.id,
      cardProductId: kartUrunu.id,
      campaignId: enIyi.campaignId,
      state: enIyi.state,
      guaranteedBenefitTL: enIyi.guaranteedBenefitTL,
      potentialBenefitTL: enIyi.potentialBenefitTL,
      nonCashBenefit: enIyi.nonCashBenefit,
      installmentMonths: enIyi.installmentMonths,
      blockingReasons: enIyi.blockingReasons,
      criticalConditions: enIyi.criticalConditions,
      calculationSteps: enIyi.calculationSteps,
      sourceUrls: [enIyi.sourceUrl],
      freshness: enIyi.freshness,
      humanApproved: enIyi.humanApproved,
    } satisfies DecisionResultV3;
  });

  return sonuclar.sort((a, b) => {
    if (DURUM_ONCELIGI[a.state] !== DURUM_ONCELIGI[b.state]) {
      return DURUM_ONCELIGI[a.state] - DURUM_ONCELIGI[b.state];
    }
    if (b.guaranteedBenefitTL !== a.guaranteedBenefitTL) {
      return b.guaranteedBenefitTL - a.guaranteedBenefitTL;
    }
    if (b.potentialBenefitTL !== a.potentialBenefitTL) {
      return b.potentialBenefitTL - a.potentialBenefitTL;
    }
    if ((b.installmentMonths ?? 0) !== (a.installmentMonths ?? 0)) {
      return (b.installmentMonths ?? 0) - (a.installmentMonths ?? 0);
    }
    return a.cardProductId.localeCompare(b.cardProductId, "tr");
  });
}
