/**
 * NE:       Her ana sayfayı o bölümün gerçek verisiyle açan KartAkıl teknoloji durum bandıdır.
 * NEDEN:    Fotoğraf veya büyük başlık tek başına sayfanın ne yaptığını ve o anda ne durumda olduğunu
 *           anlatmıyor; kullanıcı sekmeye geçtiğinde yeni bir "akıl modülü" açtığını hissetmelidir.
 * NASIL:    Ortak modül kimliğini sıra/renk/görev olarak kullanır; ekrandan gelen kısa değer ve durum
 *           metnini statik sinyal izi, cam yüzey ve tek LinearGradient içinde sunar.
 * YAN ETKİ: Ağ isteği ve sürekli animasyon yoktur; erişilebilirlikte tek açıklayıcı metin grubu olarak okunur.
 */
import { memo } from "react";
import { StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { AKIL_MODULLERI, type AltSekme } from "../akilModulleri";
import { TEMA } from "../tema";
import { CamYuzey } from "./CamYuzey";
import { KategoriIkon } from "./KategoriIkon";

type Props = {
  sekme: AltSekme;
  deger: string;
  aciklama: string;
  durum: string;
};

const SINYAL_NOKTALARI = [0, 1, 2, 3] as const;

function AkilModulBandiTemel({ sekme, deger, aciklama, durum }: Props) {
  const modul = AKIL_MODULLERI[sekme];
  return (
    <View
      style={[s.kap, { borderColor: `${modul.vurgu}42` }]}
      accessibilityRole="header"
      accessibilityLabel={`${modul.teknolojiAdi}. ${deger}. ${aciklama}. Durum: ${durum}.`}
    >
      <CamYuzey yaricap={TEMA.yaricap.buyuk} />
      <LinearGradient
        colors={[modul.vurguZemin, "rgba(15,18,24,0.08)", "rgba(15,18,24,0.72)"]}
        locations={[0, 0.52, 1]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
        pointerEvents="none"
      />
      <View style={[s.teknikCizgi, { backgroundColor: `${modul.vurgu}38` }]} pointerEvents="none" />

      <View style={s.ustSatir}>
        <View style={[s.kod, { borderColor: `${modul.vurgu}66`, backgroundColor: modul.vurguZemin }]}>
          <Text style={[s.kodYazi, { color: modul.vurgu }]}>{modul.sira}</Text>
        </View>
        <View style={s.kimlik}>
          <Text style={[s.teknolojiAdi, { color: modul.vurgu }]}>{modul.teknolojiAdi}</Text>
          <Text style={s.gorev}>{modul.gorev}</Text>
        </View>
        <View style={[s.durum, { borderColor: `${modul.vurgu}4D` }]}>
          <View style={[s.durumNokta, { backgroundColor: modul.vurgu }]} />
          <Text style={[s.durumYazi, { color: modul.vurgu }]}>{durum}</Text>
        </View>
      </View>

      <View style={s.altSatir}>
        <View style={s.degerAlani}>
          <Text style={s.deger}>{deger}</Text>
          <Text style={s.aciklama}>{aciklama}</Text>
        </View>
        <View style={s.ikonCekirdegi} pointerEvents="none">
          <View style={[s.cekirdekDis, { borderColor: `${modul.vurgu}42` }]} />
          <View style={[s.cekirdekIc, { backgroundColor: modul.vurguZemin }]}>
            <KategoriIkon kod={modul.kod} boy={23} renk={modul.vurgu} />
          </View>
        </View>
      </View>

      <View style={s.sinyal} pointerEvents="none">
        <View style={[s.sinyalHat, { backgroundColor: `${modul.vurgu}2E` }]} />
        {SINYAL_NOKTALARI.map((nokta) => (
          <View
            key={nokta}
            style={[
              s.sinyalNokta,
              {
                backgroundColor: nokta === 3 ? modul.vurgu : `${modul.vurgu}55`,
                borderColor: `${modul.vurgu}80`,
              },
            ]}
          />
        ))}
      </View>
    </View>
  );
}

export const AkilModulBandi = memo(AkilModulBandiTemel);

