/**
 * NE:       Kazanç Karnesi ekranı — kullanılan/kaçırılan kart kararlarının cihaz-içi analizi.
 * NEDEN:    KartAkıl'ın satış diferansiyatörü ("bu ay ne kazandın, neyi kaçırdın?"). Rakip
 *           araştırması dersi: rakam ŞİŞİRİLMEZ, kaynak DÜRÜST etiketlenir (v1 = "Beyan"),
 *           kaçan fırsat SUÇLAMADAN (gümüş, kırmızı değil) gösterilir; sakin premium, konfeti yok.
 * NASIL:    Hero altın rakam (count-up) + "Nasıl hesaplandı?" bir dokunuş uzakta + Bu ay/Tüm zaman
 *           çipi + ikiz şerit + foto-gerçekçi kart yüzlü kırılım + düzeltilebilir son kayıtlar akışı.
 *           Boş durum bir davet (ceza değil). Tüm veri cihazda; kaynak "Beyan" olarak işaretli.
 * YAN ETKİ: onSil yerel kaydı siler; onKararGit sekme değiştirir. Ağ/finansal veri yok.
 */
import { useEffect, useRef, useState } from "react";
import { Animated, Image, StyleSheet, Text, View } from "react-native";
import { karneOzetiOlustur, type KarneKaydi, type KartKirilimi } from "../motor/karne";
import { useSayac } from "../motor/useSayac";
import { useGiris } from "../hareket";
import { TEMA } from "../tema";
import { TutarYazi } from "./TutarYazi";
import { KrediKarti } from "./KrediKarti";
import { BosDurum } from "./BosDurum";
import { Basilabilir } from "./Basilabilir";
import { AltinHale } from "./AltinHale";
import { CamYuzey } from "./CamYuzey";

// Kazanç kutlaması — hero madalyonu (yalnız kazanç>0). 3D render; sahipsiz asset'ti, artık kutlama işareti.
const KUTLAMA = require("../../assets/durumlar/kutlama.webp");

interface Props {
  kayitlar: KarneKaydi[];
  bugunISO: string;
  hareketAzalt?: boolean;
  onSil: (id: string) => void;
  onKararGit: () => void;
}

const AYLAR = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
function kisaTarih(iso: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/u.exec(iso);
  return m ? `${Number(m[3])} ${AYLAR[Number(m[2]) - 1]}` : iso;
}
/** Kanonik para biçimi — motorun paraYaz'ı ile BİREBİR aynı (maximumFractionDigits:0).
 *  Kırmızı çizgi: karar ekranı ile karne aynı ödeme için aynı rakamı gösterir (sapma yok). */
function tl(n: number): string {
  return n.toLocaleString("tr-TR", { maximumFractionDigits: 0 });
}

/**
 * NE:       "Hangi kart kazandırdı" listesinin tek satırı — kendi sıralı giriş animasyonunu çağırır.
 * NEDEN:    useGiris bir Hook; .map() gövdesinde çağrılamaz (Hook kuralı). Her satır ayrı bileşen
 *           olunca stagger (sıraya göre yay-fizikli belir+yüksel) hook ihlali olmadan uygulanır.
 * NASIL:    useGiris(sira) → {opacity, transform}; s.kirilim satırı Animated.View'a taşınır, giriş
 *           stili diziyle eklenir. İç yapı/KrediKarti/TutarYazi BİREBİR aynı — yalnız sunum sarmalı.
 * YAN ETKİ: Yok — kazanç değeri/motor dokunulmaz; hareketAzalt=true'da useGiris animasyonu atlar.
 */
function KirilimSatiri({
  k,
  sira,
  hareketAzalt,
}: {
  k: KartKirilimi;
  sira: number;
  hareketAzalt: boolean;
}) {
  const giris = useGiris(sira, hareketAzalt);
  return (
    <Animated.View style={[s.kirilim, giris]}>
      <KrediKarti program={k.program} urunAdi={k.ad} en={68} hareketAzalt={hareketAzalt} />
      <View style={s.kirilimOrta}>
        <Text style={s.kirilimAd} numberOfLines={1}>
          {k.ad}
        </Text>
        <Text style={s.kirilimAdet}>{k.adet} ödeme</Text>
      </View>
      <TutarYazi metin={`+${tl(k.kazanc)} ₺`} boy={16} renk={TEMA.para.kazanc} />
    </Animated.View>
  );
}

/**
 * NE:       "Son işaretlediklerin" listesinin tek kaydı — kendi sıralı giriş animasyonunu çağırır.
 * NEDEN:    KirilimSatiri ile aynı Hook kuralı gerekçesi: useGiris map içinde çağrılamaz.
 * NASIL:    useGiris(sira) girişi s.kayit satırına eklenir (View → Animated.View). Silme düğmesi,
 *           kanonik para gösterimi (TutarYazi) ve "Beyan" etiketi aynen korunur.
 * YAN ETKİ: onSil yalnız ilgili kaydı siler; sunum sarmalı dışında davranış değişmez.
 */
function KayitSatiri({
  k,
  sira,
  hareketAzalt,
  onSil,
}: {
  k: KarneKaydi;
  sira: number;
  hareketAzalt: boolean;
  onSil: (id: string) => void;
}) {
  const giris = useGiris(sira, hareketAzalt);
  const kullanildi = k.durum === "kullanildi";
  return (
    <Animated.View style={[s.kayit, giris]}>
      <View style={[s.kayitNokta, kullanildi ? s.kayitNoktaAltin : s.kayitNoktaGumus]} />
      <View style={s.kayitOrta}>
        <Text style={s.kayitBaslik} numberOfLines={1}>
          {k.merchant} · {k.cardProductName ?? k.program}
        </Text>
        <Text style={s.kayitAlt}>
          {kisaTarih(k.tarih)} · {kullanildi ? "kullandın" : "başka kart"} · Beyan
        </Text>
      </View>
      <TutarYazi
        metin={`${kullanildi ? "+" : "~"}${tl(k.kazancTL)} ₺`}
        boy={14}
        renk={kullanildi ? TEMA.para.kazanc : TEMA.para.notr}
      />
      <Basilabilir
        onPress={() => onSil(k.id)}
        stil={s.silDugme}
        hareketAzalt={hareketAzalt}
        accessibilityRole="button"
        accessibilityLabel={`${k.merchant} kaydını sil`}
      >
        <Text style={s.silYazi}>✕</Text>
      </Basilabilir>
    </Animated.View>
  );
}

export function Karnem({ kayitlar, bugunISO, hareketAzalt = false, onSil, onKararGit }: Props) {
  const [zaman, setZaman] = useState<"buay" | "tum">("buay");
  const [nasilAcik, setNasilAcik] = useState(false);

  const buAyOneki = bugunISO.slice(0, 7);
  const suzulmus =
    zaman === "buay" ? kayitlar.filter((k) => k.tarih.slice(0, 7) === buAyOneki) : kayitlar;
  const ozet = karneOzetiOlustur(suzulmus, bugunISO);
  // Altın=kazanç kanonu: kazanç yokken hero/KAZANDIN altını değil nötr gümüş olur (kutlama sinyali sulanmasın).
  const kazancVar = ozet.toplamKazanc > 0;
  const heroSayac = useSayac(ozet.toplamKazanc, { hareketAzalt, sureMs: TEMA.yay.sayacMs });
  const heroMetin = `${tl(heroSayac)} ₺`;

  // Kutlama madalyonu tek-atış fade (yalnız kazanç>0; sakin premium — konfeti yok, tek sessiz beliriş)
  const kutlamaOpak = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (ozet.toplamKazanc <= 0) return;
    if (hareketAzalt) {
      kutlamaOpak.setValue(1);
      return;
    }
    kutlamaOpak.setValue(0);
    const a = Animated.timing(kutlamaOpak, { toValue: 1, duration: 520, useNativeDriver: true });
    a.start();
    return () => a.stop();
  }, [ozet.toplamKazanc, hareketAzalt, kutlamaOpak]);

  if (kayitlar.length === 0) {
    return (
      <BosDurum
        amblem="karne"
        baslik="Kazanç karnen boş"
        yazi="Henüz ödeme işaretlemedin. Bir kart önerisi al, 'Bu kartla ödedim' de — KartAkıl kazancını saymaya başlasın."
        ctaEtiket="İlk kararımı al →"
        onCta={onKararGit}
      />
    );
  }

  return (
    <View>
      {/* Zaman filtresi */}
      <View style={s.zamanSatir}>
        {(
          [
            ["buay", "Bu ay"],
            ["tum", "Tüm zaman"],
          ] as ["buay" | "tum", string][]
        ).map(([kod, etiket]) => (
          <Basilabilir
            key={kod}
            onPress={() => setZaman(kod)}
            stil={[s.zamanCip, zaman === kod && s.zamanCipSecili]}
            hareketAzalt={hareketAzalt}
            accessibilityRole="button"
            accessibilityState={{ selected: zaman === kod }}
            aria-pressed={zaman === kod}
            accessibilityLabel={`${etiket} kazançlarını göster`}
          >
            <Text style={[s.zamanYazi, zaman === kod && s.zamanYaziSecili]}>{etiket}</Text>
          </Basilabilir>
        ))}
      </View>

      {/* Hero — bu dönem kazandığın (altın YALNIZ kazanç>0; yoksa nötr gümüş) */}
      <View style={[s.hero, !kazancVar && s.heroNotr]}>
        {/* Kazanç ışıması — altın YALNIZ kazanç>0 (GD2 kanon); cam yüzey her zaman (premium hero) */}
        {kazancVar ? <AltinHale yaricap={85} /> : null}
        <CamYuzey yaricap={TEMA.yaricap.buyuk} />
        {kazancVar ? (
          <Animated.View style={[s.kutlamaMadalyon, { opacity: kutlamaOpak }]}>
            <Image source={KUTLAMA} style={s.kutlamaGorsel} resizeMode="cover" />
          </Animated.View>
        ) : null}
        <Text style={s.heroBaslik}>{zaman === "buay" ? "Bu ay kazandığın" : "Toplam kazandığın"}</Text>
        <TutarYazi metin={heroMetin} boy={46} renk={kazancVar ? TEMA.para.kazanc : TEMA.para.notr} />
        <Basilabilir
          onPress={() => setNasilAcik((a) => !a)}
          stil={s.nasilDugme}
          hareketAzalt={hareketAzalt}
          accessibilityRole="button"
          accessibilityState={{ expanded: nasilAcik }}
          aria-expanded={nasilAcik}
          accessibilityLabel={`Nasıl hesaplandığını ${nasilAcik ? "kapat" : "aç"}`}
        >
          <Text style={s.heroAlt}>
            işaretlediğin {ozet.kullanilanSayi} ödemeden · Nasıl hesaplandı? {nasilAcik ? "▲" : "▼"}
          </Text>
        </Basilabilir>
        {nasilAcik ? (
          <View style={s.nasilPanel}>
            <Text style={s.nasilYazi}>
              Bu rakam yalnız senin "bu kartla ödedim" dediğin ödemelerin tahmini net kazançlarının toplamıdır.
              Kaynağı <Text style={s.beyanVurgu}>Beyan</Text>'dır — fiş veya banka ile doğrulanmadı. Kampanya
              eşikleri tahmini olabilir. Tüm veri yalnız telefonunda saklanır; hiçbir şey sunucuya gitmez.
            </Text>
          </View>
        ) : null}
      </View>

      {/* İkiz şerit — Kazandın (altın) / Kaçan fırsat (gümüş, suçlamasız) */}
      <View style={s.ikizSatir}>
        <View style={[s.ikiz, kazancVar ? s.ikizAltin : s.ikizGumus]}>
          <Text style={s.ikizEtiket}>KAZANDIN</Text>
          <TutarYazi
            metin={`${tl(ozet.toplamKazanc)} ₺`}
            boy={19}
            renk={kazancVar ? TEMA.para.kazanc : TEMA.para.notr}
          />
          <Text style={s.ikizAlt}>{ozet.kullanilanSayi} ödeme</Text>
        </View>
        <View style={[s.ikiz, s.ikizGumus]}>
          <Text style={s.ikizEtiket}>KAÇAN FIRSAT</Text>
          <TutarYazi metin={`${tl(ozet.toplamKacan)} ₺`} boy={19} renk={TEMA.para.notr} />
          <Text style={s.ikizAlt}>{ozet.kacirilanSayi} kez başka kart</Text>
        </View>
      </View>
      {ozet.toplamIsaret > 0 ? (
        <Text style={s.oranNot}>
          İşaretlediğin ödemelerin %{ozet.kullanimOrani}'ünde en kazançlı kartı kullandın.
        </Text>
      ) : null}

      {/* Kart bazlı kırılım — gerçek kart yüzleri, en çok kazandıran üstte */}
      {ozet.kartKirilimi.length > 0 ? (
        <View style={s.bolum}>
          <Text style={s.bolumBaslik}>Hangi kart kazandırdı</Text>
          {ozet.kartKirilimi.map((k, i) => (
            <KirilimSatiri
              key={`${k.program}-${k.ad}`}
              k={k}
              sira={i}
              hareketAzalt={hareketAzalt}
            />
          ))}
        </View>
      ) : null}

      {/* Son işaretlenenler — düzeltilebilir/silinebilir akış */}
      {ozet.sonKayitlar.length > 0 ? (
        <View style={s.bolum}>
          <Text style={s.bolumBaslik}>Son işaretlediklerin</Text>
          {ozet.sonKayitlar.slice(0, 12).map((k, i) => (
            <KayitSatiri key={k.id} k={k} sira={i} hareketAzalt={hareketAzalt} onSil={onSil} />
          ))}
        </View>
      ) : (
        <View style={s.donemBos}>
          <Text style={s.donemBosYazi}>
            Bu dönemde işaret yok. "Tüm zaman"a bak ya da yeni bir karar al.
          </Text>
        </View>
      )}

      {/* Alt güven notu */}
      <Text style={s.guvenNot}>
        Bu rakamlar senin beyanına dayanır ve yalnız cihazında saklanır. Kart numaranı, harcamanı ve konumunu
        asla tutmayız.
      </Text>
      <View style={{ height: TEMA.bosluk.xxl }} />
    </View>
  );
}

