/**
 * NE:       KararSatiri güven durumunu büyük cevap ve alternatif satırının ortak sunum bayraklarına çevirir.
 * NEDEN:    Bileşenlerden biri guaranteed sonucu “kontrol gerekli” gösterirse aynı motor kararı iki farklı
 *           güven mesajı verir; bu ayrım tek ve test edilebilir bir sözleşmede olmalıdır.
 * NASIL:    Vade bilgisini ayrı tutar; legacy teyit ile V3 guaranteed/potential/unknown/ineligible
 *           durumlarını birbirine karıştırmadan rozet, uyarı ve kesinlik bayrakları üretir.
 * YAN ETKİ: IO veya UI çizimi yoktur; iki bileşen yalnız bu saf sonucu tüketir.
 */
import type { KararSatiri } from "../tipler";

export interface KararGuvenSunumu {
  vadeBilgisi: boolean;
  v3Kesin: boolean;
  potansiyel: boolean;
  bilinmeyen: boolean;
  uygunDegil: boolean;
  legacyTeyit: boolean;
  teyitGerekli: boolean;
  uyariliDurum: boolean;
  guvenRozeti: string | null;
}

export function kararGuvenSunumu(satir: KararSatiri): KararGuvenSunumu {
  const vadeBilgisi = satir.tip === "vade";
  const v3Kesin = satir.guvenDurumu === "guaranteed";
  const potansiyel = satir.guvenDurumu === "potential";
  const bilinmeyen = satir.guvenDurumu === "unknown";
  const uygunDegil = satir.guvenDurumu === "ineligible";
  const legacyTeyit =
    !vadeBilgisi &&
    satir.guvenDurumu !== "verified" &&
    !v3Kesin &&
    !potansiyel &&
    !bilinmeyen &&
    !uygunDegil;
  const teyitGerekli = legacyTeyit || potansiyel || bilinmeyen;
  const guvenRozeti = v3Kesin
    ? "doğrulandı"
    : potansiyel
      ? "koşula bağlı"
      : bilinmeyen
        ? "bilgi eksik"
        : uygunDegil
          ? "uygun değil"
          : legacyTeyit
            ? "teyit gerekli"
            : null;

  return {
    vadeBilgisi,
    v3Kesin,
    potansiyel,
    bilinmeyen,
    uygunDegil,
    legacyTeyit,
    teyitGerekli,
    uyariliDurum: teyitGerekli || uygunDegil,
    guvenRozeti,
  };
}
