import { registerRootComponent } from "expo";
import { createElement } from "react";
import { SafeAreaProvider } from "react-native-safe-area-context";

import App from "./App";
import { HataSiniri } from "./src/bilesenler/HataSiniri";

// registerRootComponent, AppRegistry.registerComponent('main', () => App) çağırır.
// SafeAreaProvider (en dış) → cihaz çentiği/home-indicator boşlukları; HataSiniri → çökme koruması.
// Bir render hatası tüm uygulamayı beyaz/boş ekrana düşürmesin ("kusursuz çalışma").
function KartAkilKok() {
  return createElement(SafeAreaProvider, null, createElement(HataSiniri, null, createElement(App)));
}

registerRootComponent(KartAkilKok);
