import type { ImageSourcePropType } from "react-native";

export interface ProgramMarka {
  /** Resmi ana renk (açık zeminde) */
  renk: string;
  /** Koyu grafit zeminde iyi görünen ton (nokta/vurgu için) */
  koyuZemin: string;
  logo: ImageSourcePropType;
  /** Bankkart gibi yatay/alçak logolar genişlik referansıyla yerleştirilir */
  yatayMi?: boolean;
  /** Foto-gerçekçi kredi kartı yüzü degradesi (2-4 hex; sol-üst → sağ-alt) */
  kartGradyan?: string[];
  /** Kart yüzü AÇIK renkse (Axess sarı gibi) yazı/numara koyu olur */
  kartYaziKoyu?: boolean;
  /** Kartın çıktığı ödeme ağları (ilki kart görselinde gösterilir) */
  aglar?: string[];
}

export interface UrunProgramGorunumu {
  markaAdi: string;
  kartGradyan: [string, string, ...string[]];
}

