/**
 * Bir kartın KrediKarti yüzü için görünüm override'ları — TEK KAYNAK.
 * Öncelik: ürün-özel (Maximiles Black siyah) → program görünümü (amex/miles/shopfly) →
 * (döndürülmeyen alanlar KrediKarti içindeki PROGRAM_MARKA / varsayılana düşer).
 * Tüm kart yüzeyleri (seçici · karar · karne) bunu çağırır → aynı kart her ekranda tutarlı görünür.
 */
export function kartGorunumu(
  programId: string | undefined,
  urunId?: string
): { markaAdi?: string; kartGradyan?: [string, string, ...string[]]; kartYaziKoyu?: boolean; imza?: KartImza } {
  const ozel = urunId ? KART_URUN_GORUNUMU[urunId] : undefined;
  const prog = programId ? URUN_PROGRAM_GORUNUMU[programId] : undefined;
  return {
    markaAdi: ozel?.markaAdi ?? prog?.markaAdi,
    kartGradyan: ozel?.kartGradyan ?? prog?.kartGradyan,
    kartYaziKoyu: ozel?.kartYaziKoyu,
    imza: ozel?.imza,
  };
}

export function programTon(program: string): string {
  return PROGRAM_MARKA[program]?.koyuZemin ?? "#9ba0aa";
}

/** #rrggbb → rgba(r,g,b,a) — marka rengini cam/degrade katmanlarında yumuşak kullanmak için */
export function hexA(hex: string, alpha: number): string {
  const t = hex.replace("#", "");
  const r = parseInt(t.slice(0, 2), 16);
  const g = parseInt(t.slice(2, 4), 16);
  const b = parseInt(t.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}
