/**
 * NE:       Kart-ekleme akışının 1. sahnesi — BANKA seçimi ("önce banka, sonra kart").
 * NEDEN:    Mehmet abi (2026-07-21): "app basit sekmeli seçim programı olmamalı; önce banka
 *           seçtir sonra kart." Kullanıcı kartını önce bankasından tanır; her ekran tek karar =
 *           sürtünme düşer. Araştırma sentezi de bunu doğruladı (banka→kart sahne dizisi).
 * NASIL:    KATALOG.issuers 2 sütun grid; her banka O BANKANIN baskın program rengiyle cam yüzey
 *           (kutusuz — kanon), banka adı + kart sayısı + cüzdandaki seçili rozet; sıralı yay girişi
 *           (useGiris); dokunuşta seçim haptiği + onSec. Marka rengi telif-güvenli (tek renk korunmaz).
 * YAN ETKİ: Yok — yalnız seçilen issuerId'yi üst bileşene iletir; ağ/dosya erişimi yok.
 */
import { Animated, Image, StyleSheet, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import katalogVerisi from "../veri/v3-esleme-katalogu.json";
import type { V3EslemeKatalogu } from "../motor/v3Gecis";
import { PROGRAM_MARKA } from "../marka/markalar";
import { useGiris } from "../hareket";
import { dokunsalSecim } from "../dokunsal";
import { TEMA } from "../tema";
import { Basilabilir } from "./Basilabilir";

const KATALOG = katalogVerisi as unknown as V3EslemeKatalogu;
const VARSAYILAN_GRADYAN: [string, string, ...string[]] = ["#2a2d35", "#16181d", "#0e1014"];

interface Props {
  /** Cüzdanda seçili kart id'leri (banka başına rozet için) */
  seciliIds: string[];
  onSec: (issuerId: string) => void;
  hareketAzalt?: boolean;
}

/** Bir bankanın baskın program adını bul (en çok karta sahip program) → gerçek kart rengi için. */
function bankaProgramAdi(issuerId: string): string | undefined {
  const say = new Map<string, number>();
  for (const urun of KATALOG.cardProducts) {
    if (urun.issuerId === issuerId && urun.active) {
      say.set(urun.programId, (say.get(urun.programId) ?? 0) + 1);
    }
  }
  const ana = [...say.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
  return ana ? KATALOG.programs.find((p) => p.id === ana)?.name : undefined;
}

function bankaGradyani(issuerId: string): [string, string, ...string[]] {
  const ad = bankaProgramAdi(issuerId);
  const g = ad ? PROGRAM_MARKA[ad]?.kartGradyan : undefined;
  return g && g.length >= 2 ? (g as [string, string, ...string[]]) : VARSAYILAN_GRADYAN;
}

function BankaHucresi({
  issuerId,
  ad,
  kartSayisi,
  seciliSayi,
  sira,
  onSec,
  hareketAzalt,
}: {
  issuerId: string;
  ad: string;
  kartSayisi: number;
  seciliSayi: number;
  sira: number;
  onSec: (id: string) => void;
  hareketAzalt?: boolean;
}) {
  const giris = useGiris(sira, hareketAzalt);
  const gradyan = bankaGradyani(issuerId);
  const programAdi = bankaProgramAdi(issuerId);
  const marka = programAdi ? PROGRAM_MARKA[programAdi] : undefined;
  return (
    <Animated.View style={[s.hucreSar, giris]}>
      <Basilabilir
        onPress={() => {
          dokunsalSecim();
          onSec(issuerId);
        }}
        stil={s.hucre}
        hareketAzalt={hareketAzalt}
        accessibilityRole="button"
        accessibilityLabel={`${ad}, ${kartSayisi} kart${seciliSayi > 0 ? `, ${seciliSayi} tanesi cüzdanında` : ""}`}
      >
        <LinearGradient
          colors={gradyan}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
        />
        {/* üst ışık parlaması — cam/metal his */}
        <LinearGradient
          colors={["rgba(255,255,255,0.18)", "rgba(255,255,255,0.03)", "transparent"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
          pointerEvents="none"
        />
        {seciliSayi > 0 && (
          <View style={s.rozet}>
            <Text style={s.rozetYazi}>{seciliSayi}</Text>
          </View>
        )}
        <View style={s.hucreIcerik}>
          {marka && (
            <Image
              source={marka.logo}
              style={[s.bankaLogo, { width: marka.yatayMi ? 86 : 58 }]}
              resizeMode="contain"
            />
          )}
          <Text style={s.bankaAd} numberOfLines={2}>
            {ad}
          </Text>
          <Text style={s.kartSayi}>
            {kartSayisi} kart{seciliSayi > 0 ? ` · ${seciliSayi} cüzdanında` : ""}
          </Text>
        </View>
      </Basilabilir>
    </Animated.View>
  );
}

export function BankaSecimi({ seciliIds, onSec, hareketAzalt = false }: Props) {
  const seciliSeti = new Set(seciliIds);
  const bankalar = KATALOG.issuers
    .map((issuer) => {
      const kartlar = KATALOG.cardProducts.filter((u) => u.issuerId === issuer.id && u.active);
      const seciliSayi = kartlar.filter((u) => seciliSeti.has(u.id)).length;
      return {
        id: issuer.id,
        ad: issuer.aliases[0] ?? issuer.name,
        kartSayisi: kartlar.length,
        seciliSayi,
      };
    })
    .filter((b) => b.kartSayisi > 0)
    // Cüzdanda kartı olan bankalar önce, sonra kart sayısına göre
    .sort((a, b) => b.seciliSayi - a.seciliSayi || b.kartSayisi - a.kartSayisi);

  return (
    <View style={s.kap}>
      <Text style={s.baslik}>Hangi banka?</Text>
      <Text style={s.altBaslik}>Kartının bankasını seç, kartlarını gerçek görünümüyle getireyim.</Text>
      <View style={s.grid}>
        {bankalar.map((b, i) => (
          <BankaHucresi
            key={b.id}
            issuerId={b.id}
            ad={b.ad}
            kartSayisi={b.kartSayisi}
            seciliSayi={b.seciliSayi}
            sira={i}
            onSec={onSec}
            hareketAzalt={hareketAzalt}
          />
        ))}
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  kap: { gap: TEMA.bosluk.s },
  baslik: { color: TEMA.renk.yazi, fontSize: 20, fontWeight: "800" },
  altBaslik: { color: TEMA.renk.yaziSoluk, fontSize: 13, lineHeight: 18, marginBottom: TEMA.bosluk.s },
  grid: { flexDirection: "row", flexWrap: "wrap", gap: TEMA.bosluk.m },
  hucreSar: { flexGrow: 1, flexBasis: "45%" },
  hucre: {
    height: 92,
    borderRadius: TEMA.yaricap.orta,
    overflow: "hidden",
    justifyContent: "flex-end",
    borderWidth: 1,
    borderColor: "rgba(255,255,255,0.08)",
  },
  hucreIcerik: { padding: TEMA.bosluk.m, gap: 4 },
  bankaLogo: { height: 17, alignSelf: "flex-start", marginBottom: 3, opacity: 0.96 },
  bankaAd: {
    color: "#ffffff",
    fontSize: 16,
    fontWeight: "800",
    textShadowColor: "rgba(0,0,0,0.35)",
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 3,
  },
  kartSayi: { color: "rgba(255,255,255,0.82)", fontSize: 11.5, fontWeight: "600" },
  rozet: {
    position: "absolute",
    top: 8,
    right: 8,
    minWidth: 22,
    height: 22,
    paddingHorizontal: 6,
    borderRadius: 11,
    backgroundColor: TEMA.renk.altin,
    alignItems: "center",
    justifyContent: "center",
  },
  rozetYazi: { color: "#1a1206", fontSize: 12, fontWeight: "900" },
});
